#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber (20) ---
patchFile('siman_018/mechaber/part-001.txt', 'mechaber', {
  '1#main': `The law of checking the shechitah knife and its flaws. In it are 20 seifim. One who slaughters with a checked knife and it is found flawed (even from the side) (my humble opinion) — behold it is neveilah; even if it touched the joint-bone one does not attribute that it was flawed by it after shechitah, but rather we are concerned lest it was flawed in the hide, and it turns out he slaughtered with a flawed knife — and even in fowl.`,
  '2#main': `The measure of a flaw is any amount whatsoever, provided that it catches in it any amount whatsoever, even a hair's-breadth.`,
  '3#main': `One must check the knife before shechitah. If he did not check — he may not slaughter. If he transgressed and did not check it first and afterward checked it and found it good — his shechitah is valid.`,
  '4#main': `A knife that one checked on holacha u'va and did not feel that it has a flaw, and when he brought it back on hava'ah he felt that it has a flaw — this is called masuchseches: if he slaughtered with it by way of holacha alone and did not bring back, his shechitah is valid; if he brought back, his shechitah is invalid. And this is when he felt it before shechitah; but if he found his knife good before shechitah and after shechitah found in it a masuchseches flaw and said, "It is clear to me that I did only holacha alone" — his shechitah is invalid. {Rama: And some are stringent that any masuchseches is forbidden until it stands at the very head of the knife if he slaughtered on holacha, and at the very end of the knife if he slaughtered on hava'ah (old shechitah laws and Semak glosses and the above poskim); and since we are not expert where is called the head of the knife, one should declare treifah everything (my humble opinion; also the gloss in Mahari Weil's shechitah and so it appears in Mordechai and Kol Bo and Agudah and so writes the Agur — such is the custom).}`,
  '5#main': `A knife that has many flaws — even if all are masuchseches, even if he slaughtered with it b'dieved — it is invalid. For since its flaws are numerous we are concerned lest he withdrew his hand slightly and did not feel it.`,
  '6#main': `A sharp knife that was honed and is not smooth but its touch is like the touch of the head of an ear of grain that tangles in the finger — since it has no flaw, one slaughters with it (Rambam's wording there, law 18). {Rama: And we do not practice slaughtering with it, because we are not expert in the matter (Agur and Beit Yosef and Maharshal chapter 1, siman 37).}`,
  '7#main': `A knife whose edge is smooth and is not sharp — since it has no flaw, one slaughters with it, even if he did holacha u'va all day until he slaughtered — his shechitah is valid (Rambam's wording there, law 17) (and see below siman 23, that in an animal sometimes it is treifah, and so too Beit Yosef).`,
  '8#main': `A knife that rises and falls like a serpent and has no flaw — one slaughters with it l'chatchila.`,
  '9#main': `Checking the knife requires avshara, atufra, and three directions — that is, he passes it and brings it back on the flesh of his finger and afterward passes and brings back on his fingernail from three of its directions, which are its edge and its two sides, so that there be no flaw at all; and he should check slowly and with intent of heart so that his heart not turn to other things; and he must shift the fingernail after a bit of checking, lest the fingernail was flawed by the point of the knife; and perhaps there is a flaw on the sides that he will not feel, because it passes within the flaw of the fingernail. {Rama: And he should not check both sides of the knife together, but each one by itself (Mahari Weil).}`,
  '10#main': `A knife that has a flaw — it is forbidden to slaughter with it, even if he intends to slaughter not opposite the flaw; and on Yom Tov they practice permitting wrapping a cloth on the flaw, since one cannot hone it; and if it is a time of distress and he has no preparation to hone it, even on a weekday it is permitted to slaughter by wrapping a cloth on the flaw. {Rama: And see above siman 6, seif 1: a knife that has two edges — one must check both sides (Tur siman 6).}`,
  '11#main': `One who slaughters many animals or many fowl must check between each and every one; for if he did not do so and checked at the last and the knife was found flawed — behold all are doubtful neveilah, even the first. {Rama: And one who wishes to bring himself into this doubt need not check the knife between shechitah and shechitah (Terumat HaDeshen siman 184 and Beit Yosef in the name of Baal HaMaor and Rashba; and see seif kaf 17).}`,
  '12#main': `Even though he checked the knife before shechitah, he must return and check after shechitah; and this is when the knife is before us; but if it was lost — his shechitah is valid, since he checked it before shechitah, even if he slaughtered with it many one after another; and if he touched the joint-bone of one of them — one should be stringent and be concerned for all those slaughtered afterward (Tur in the name of the Geonim and Rashba in the name of his teachers and Ran).`,
  '13#main': `If he slaughtered with a checked knife and it was lost before he could check it after shechitah, and afterward it was found and it was flawed — his shechitah is valid, since it went out in permissibility; and this one that was found flawed — say that he broke bones in it and he was not aware, for we establish the knife in its presumption.`,
  '14#main': `If he did not check the knife and slaughtered with it and it was lost after shechitah — his shechitah is invalid. In what case? With an ordinary knife; but a butcher who has a special knife for shechitah and a special place where he always hides it — it is in the presumption of being checked, and if he slaughtered with it without checking and it was lost — his shechitah is valid. {Rama: And it is fitting for every butcher to have a special knife for shechitah, and it is forbidden to do with it any other matter, and he should hide it so that it not be flawed (Rashi and Kol Bo and Hagahot Maimoni, Laws of Shechitah siman 6; and see Tur and Beit Yosef there); nevertheless he may not slaughter with it l'chatchila without checking (Rashba and Beit Yosef there).}`,
  '15#main': `One who slaughters with a checked knife and after shechitah broke bones in it — not by way of holacha u'va (Rashba and R' Yitzchak and R' Yerucham) — and checked it and a flaw was found — his shechitah is valid, for we attribute that it was flawed by breaking the bones; and so anything similar, such as that it fell on hard ground — but specifically when we saw that it fell on its point; but from doubt we do not attribute to say that it fell on its point; and if he broke in it the joint-bone — even by way of breaking we do not attribute, because it is soft. {Rama: And there is no distinction in all this whether he checked the knife first close to shechitah or it was in the presumption of being checked first and he did not check it close to shechitah — for even so it is called a checked knife (my humble opinion, from Mordechai's glosses, chapter 1 of Chullin, and Hagahot Maimoni and Agudah; and see seif kaf 64).}`,
  '16#main': `If he checked the knife after shechitah and hid it, and afterward it was found flawed — we have no concern, for say that it was flawed by something else or that he broke bones in it and he was not aware.`,
  '17#main': `A butcher who did not show his knife to a sage (and it was found good) (Tur) — they would excommunicate him. {Rama: And if it was found flawed they would excommunicate him and remove him (Tur); and if it was found good the sage may forgive and he need not excommunicate him (Alfasi's glosses, chapter 1 of Chullin);} and nowadays they practice appointing known men over shechitah and checking, and the sages forgave their honor because they are careful and diligent; and much settling of mind and fear of Heaven is required for checking the knife — do you not see that a person may check two or three times and not feel a thin flaw, and afterward it is found, because he prepared his heart at the end; and the quality of the sense of touch is according to intent of heart (Rabbenu Yonah in Shaarei Teshuvah).}`,
  '18#main': `The butcher must take wages from treifot as from kosher ones. {Rama: So that he not come to be lenient to declare fit in order to receive his wages from the kosher (Beit Yosef in the name of Rivash); and therefore in some places they practice that a person does not slaughter and check for himself, but only those appointed by the community.}`,
  '19#main': `Reuven said to Shimon, "Check this knife," and he checked it twice as required and gave it to Reuven; and Reuven was going to slaughter and Levi took it from his hand and it was found flawed (and Reuven apologizes and says that he still wanted to check it properly) (all in Rashba's responsum siman 494) — his actions prove against him that the checking sufficed for him; and therefore they remove him; and if the matters appear like an error and he is a kosher person — they restore him, provided he accepts upon himself that he will not again do such a thing.`,
  '20#main': `A butcher in whose knife-head a flaw was found, and he said, "This flaw is because I cover fowl blood on the knife-head, and when I slaughter I am careful that I do not touch the flaw" — they remove him; and it is close to say that the utensils are forbidden.`,
});

// --- siftei-kohen (34) ---
patchFile('siman_018/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '1#א': `<b>Behold it is neveilah.</b> Explanation: doubtful neveilah; and as he writes below, "but rather we are concerned," and so too at the end of seif 11; and so Rambam chapter 1 of Laws of Shechitah and Kol Bo and Semak siman 167 and other poskim; therefore the Mechaber wrote below siman 28, seif 20, that in such a case one covers without a blessing — see there.`,
  '1#ב': `<b>But rather we are concerned, etc.</b> Because an animal while alive stands in a presumption of prohibition, and it does not leave prohibition until you know with what it was slaughtered; and since a doubt arose in it, it has not been clarified to you that it was slaughtered properly (as below, end of siman 25). End of Talmud.`,
  '1#ג': `<b>And even in fowl.</b> Even if he also touched the joint-bone — for there are two reasons to be lenient: its measure is soft, and he also touched the joint-bone — nevertheless we are concerned lest it was flawed in the hide; and so Bach.`,
  '2#_': `<b>The measure of a flaw is any amount.</b> Explanation: if a flaw of any amount is found, it is invalid; but l'chatchila one need not check except avshara and atufra, as below seif 9, because we are not concerned for a flaw of any amount; and so Maharshal chapter 1 of Chullin siman 38, not like Bach who ruled to be lenient that it is not rendered treifah by a flaw of any amount but only by the measure of catching a fingernail — for we have only our custom; Heaven forbid that we be lenient thus; and since he saw that they check on the fingernail, he understood that our custom is that any flaw that does not catch a fingernail is valid — but it is not so, for the custom is plainly to invalidate even a flaw of any amount, as Beit Yosef and Darkei Moshe and Maharshal and other acharonim write, and as Rambam and Kol Bo and Ramban and Rashba and Ran and their colleagues hold; only that l'chatchila we are not concerned for a flaw of any amount and it suffices for us with checking the fingernail, as he writes; and so it appears from Taz as I explained; also what Bach said that from Tosafot's words it appears that specifically the measure of catching a fingernail is required — it is not so, and proof: for Kol Bo too wrote like Tosafot, and so Taz — see there.`,
  '3#_': `<b>One must check the knife before, etc.</b> And one may not rely on what he intends to check after shechitah (Tur); therefore the Mechaber doubled and wrote "and if he did not check he may not slaughter," meaning even if he relies that he will check it afterward it is forbidden; and the reason Rashba wrote: lest he forget to check after shechitah, and behold he is like one eating neveilah — Beit Yosef brings it, and so it appears in Tur. And in Perishah, seif 8, he wrote a reason: because it is said "and you shall slaughter them" and "you shall eat" — and it is difficult, for in the Talmud (daf 17b) they derive knife-checking from the Torah: "and you shall slaughter them and you shall eat" — it is obvious; since when it pierces it is treifah, it requires checking by a sage — they must mean thus; and see siman 2, seif kaf 8 [YD].`,
  '4#א': `A knife that one checks on holacha, etc. — meaning that he passes the knife on the finger; and so Perishah explains.`,
  '4#ב': `<b>And if he brought back.</b> Even if he did not do holacha — his shechitah is invalid, because the point strikes the siman and tears it.`,
  '4#ג': `<b>His shechitah is invalid.</b> The reason the poskim wrote: anything that is not dependent on a person, he does and is not aware.`,
  '4#ד': `<b>Until it stands at the head of the knife, etc.</b> For otherwise the head of the knife weakens the hide and flesh, and afterward the point tears.`,
  '4#ה': `<b>One should declare treifah everything.</b> And even masuchseches from the side; but those markings on the sides of knives — it appears to me permitted, for in a long knife there is space in such a case; and so Maharshal, and Bach brings it; and see above siman 9.`,
  '7#א': `<b>And see below siman 23, etc.</b> Meaning: there, seif 4, it is explained that one who slaughters with a knife that is not sharp and pauses the measure of shehiyah in the last minority of the first siman — it is invalid; and the reason is explained there: since the majority of the first siman was cut, it is as if the whole was cut, and what he does holacha u'va in the remaining minority is as if he does holacha u'va with its hand or foot; therefore in fowl, whose fitness is in one siman (as below siman 21), shehiyah is not considered — for as soon as he cut the majority of one siman in fowl, behold its shechitah is finished; and even though we hold below siman 23 that shehiyah, even any amount, invalidates, even in the last minority, whether in fowl or in animal — that is specifically actual shehiyah; not so one who slaughters with a bad knife, since he always does holacha u'va — examine this.`,
  '7#ב': `<b>Sometimes treifah.</b> To exclude: not that there was shehiyah of the measure of shehiyah; or to exclude: where he intended and placed the two simanim together one next to the other and slaughtered both — in this case it is well settled what Bach wondered on Taz, who wrote in the general case "one slaughters," and it further implies even l'chatchila; and below they wrote "one who slaughters with a knife that is not sharp," etc. — here they came only to teach the law of the knife, and it deals with a case where there is no shehiyah, such as where he places the two simanim together one next to the other, as I explained. I again found in Bach siman 23 that he wrote: perhaps according to what they invalidate shehiyah of any amount, everyone who slaughters with a bad knife — the shechitah is always invalid, and there is no measure to the matter — end of his words; and it requires study; and also in Taz, this siman and siman 24, it implies that specifically a measure of shehiyah is required; and so other acharonim wrote in the general case regarding an animal, measure of shehiyah; however, certainly l'chatchila one should not slaughter with it even fowl, since l'chatchila one must slaughter two simanim in fowl as in animal; and so Bach there; and see below siman 23, seif kaf 9.`,
  '8#_': `<b>That rises and falls, etc.</b> It appears that even two or three rises and falls are valid l'chatchila for slaughter; for if you would say that two are forbidden because the second tears — then also with one, the hollow of the knife weakens, as they say in the Talmud; and furthermore, we validate rising and falling even for holacha u'va many times — let us say that on the first time it weakens and on the second it tears; and such is the practice, not like Bach who wrote here a strange matter, not accepted, to forbid two or three rises and falls — see there; so too the Gaon, may his memory be blessed.`,
  '9#_': `<b>And he must shift the fingernail, etc.</b> And he wrote in Mishmeret HaBayit, page 7a, in the name of Raavad: one should rinse the knife before checking, because blood sometimes congeals in the flaw; and Raavad testified that such happened to him — he checked and did not find a flaw, and afterward when he rubbed it in water he found a flaw — see there.`,
  '10#_': `<b>It is forbidden to slaughter, etc.</b> But b'dieved it is valid even if he did not wrap a cloth on the flaw, if he says, "It is clear to me that I did not touch it," as Rabbenu Yerucham wrote in siman 6; and this is specifically when he knew before shechitah that there is a flaw; but if he did not know and afterward said, "It is clear to me that I did not touch," such as where the flaw is above the middle of the knife and he said, "It is clear to me that I slaughtered only in what is below the middle" — even b'dieved it is forbidden, for anything not dependent on a person, he is not aware, as above end of seif 4; and see siman 6 where the laws of wrapping cloth on a flaw are explained.`,
  '11#א': `<b>He must check, etc.</b> It implies checking as required — avshara, atufra, and three directions; and so Darkei Moshe in the name of Maharil, not like what is written in the name of old shechitah laws that one need not check twelve times between shechitah and shechitah, because the spirit of the sages does not rest on him to interrupt — so too between blessing and second shechitah — end of his words; and it is not clear, for needs of shechitah are not an interruption, as below siman 19.`,
  '11#ב': `<b>And even the first.</b> For we are concerned lest in the hide of the first it was flawed, as above seif 1.`,
  '11#ג': `<b>And one who wishes, etc.</b> So too it appears from the Mechaber's words and Rambam and Rif, who wrote that if he did not do so — it implies specifically from this reason he must check between each and each, as is in Terumat HaDeshen; and so is the law in Kol Bo and Semag and other poskim; and so Maharshal, chapter 1 of Chullin siman 19; and so it appears to me plainly from Rif's and Rosh's words, who wrote after what they ruled the halachah like Rav Huna — "he did not break bones in it" — therefore checking is required between each and each, etc.; and so it is proven in Shaarei Torah siman 2, who wrote: if he slaughtered with a checked knife and after shechitah a flaw was found in it — all are invalid; therefore it is good to check the knife between each and each — end of his words; and so it is proven in the Talmud in what they say: like whom? Like R' Hoshaya — to invalidate the first; and so in Rashba's chiddushim, daf 14 end of 3 — for so the sugya is proven: what Rav Kahana required checking between each and each is good advice and not an obligation, etc.; and so is the view of many poskim, not like Bach who attacked Rabbenu Yerucham and wrote that Rosh and Tur are later — they saw Rif's wording and it did not seem right to them, therefore they changed the wording and wrote "and if"; but from Tur's words there is no necessity, and from Rif and Rosh it is plainly proven — aside from the wording; however, they must not take from the slaughtered animals to eat before checking the knife after shechitah.`,
  '11#ד': `<b>To bring himself into, etc.</b> And Taz wrote: if he slaughters for others and did so without permission and afterward the knife was found flawed — he must pay, even if he slaughters for free, as the law of a damager with his hands — end of his words; and see Yam Shel Shlomo, chapter HaGozel Eitzim, siman 23, and in Choshen Mishpat siman 306.`,
  '12#א': `<b>And even if he slaughtered with it many, etc.</b> And we do not say that perhaps he touched the joint-bone of the first and it was flawed, or that because he slaughtered many animals with it it was flawed.`,
  '12#ב': `<b>And if he touched the joint-bone of one and the knife was lost, one should be stringent, etc.</b> Meaning: for stringency they say that the joint-bone flaws by touch alone; but not for leniency, as above seif 1; and so in Sedei Chemed.`,
  '13#_': `<b>His shechitah is valid.</b> Thus Rosh there: it is an extra stringency to attribute to the hide more than to the joint-bone; therefore, where he knows for certain that he did not break bones, we attribute for stringency — say it was flawed in the hide, even though it is more common that it flaws on the joint-bone than on the hide — we forbid it; but where the knife was lost and we doubt whether he broke bones in it, and an additional doubt is added — we permit it, etc.; therefore we are lenient in a light matter — attribute to something else — end of his words; and in the body of the question there another reason is explained: since the knife went out in permissibility, it went out; and this that was found flawed — say he broke bones in it and he was not aware, for we establish the knife in its presumption; and say it was not flawed — end of his words; and see seif kaf 24.`,
  '14#א': `<b>His shechitah is valid.</b> And we are not concerned lest with its standing it was flawed by itself. Rashba.`,
  '14#ב': `<b>And he should hide it so it not be flawed, etc.</b> Lest he slaughter with it without checking and the knife be lost and we rely on its presumption that it was checked before — and perhaps he made it flawed by what he used it for; so Rashba in Terumat HaDeshen, and Beit Yosef brings it, siman 6 — see there.`,
  '15#א': `<b>But from doubt we do not attribute to say that it fell on its point.</b> The reason: because there is a double doubt for prohibition — one, that perhaps it did not fall on its point; and even if you say it fell on its point, perhaps it was not flawed on the ground, for ground does not certainly flaw, as in Rosh's responsum, general principle 20, siman 14; and so Maharshal there: since there is a doubt, it is forbidden — see there. And it is difficult in general for above seif 13, where the knife was lost and afterward found flawed, that it is valid — there there is only one doubt, that perhaps he broke bones in it and was not aware, as explained there; and furthermore, here, since the knife is before us and checking is required, it has not gone out ever in a presumption of permissibility; but there, since it was lost, it went out in a presumption of permissibility, as explained there; therefore even if found afterward we establish it in its presumption of permissibility and say: perhaps he broke bones in it afterward and was not aware; and perforce one must distinguish thus, for Rosh in that responsum ruled like above seif 13, and in his rulings wrote as Taz wrote here; and so Maharshal, chapter 1 of Chullin, siman 18 and 19 — these two laws. And I did not grasp Bach's final view, who lengthened in his words and made Rosh as one who does not stand by his word — that in his rulings he retracted from what he said in the responsum, and an error went out from before the rulers — see Maharshal; and the matter is clear as written; examine; and so Taz and Zivchei Tzedek and Sefer Lamed Chet bring these two laws in the general case for halachic ruling; and so Darkei Moshe rules like Rosh's responsum.`,
  '15#ב': `<b>Even by way of breaking, etc.</b> It requires study, for it appears from the poskim that by way of breaking one attributes; and what appears from the Mechaber from Ran is not necessary, for Ran refers to where he broke by holacha u'va; and know, for Ran wrote on this and so Rashba and in Rashba's chiddushim, daf 14 and 15, and in Terumat HaDeshen end of daf 17 — it plainly implies thus — see there.`,
  '16#_': `<b>If he checked the knife, etc.</b> At first glance it is difficult why the Mechaber wrote this law — is it not all the more so from what he wrote in seif 13? And it must be that therefore he was precise and wrote that we say: perhaps it was flawed by something else or he broke bones in it, etc.; and above he wrote only the reason that we say he broke bones in it alone, because above it deals where it is not known whether he broke bones in it or not, as also appears from Rosh's responsum that I brought in seif kaf 21; therefore they say he broke bones in it; but here he informs us: even though it is known clearly that he did not break bones in it, such as where he placed it in a box — nevertheless, since he checked it after shechitah, say it was flawed by something else by itself or he broke bones in it, etc.; and even though above end of seif 14 we are not concerned lest with its standing it was flawed by itself — there, because there is no unseemliness before us, therefore we establish it in its presumption; but here, behold the flaw is before you; perforce they say: with its standing it was flawed by itself by something else.`,
  '17#א': `<b>And when it was found good the sage may forgive, etc.</b> Alfasi's glosses; and it appears that he holds like Rashi and Ran, that they excommunicated him when he did not show his knife to a sage because of the sage's honor, as below siman 242; and it is possible to explain that they excommunicated for the rabbi's honor, therefore the sage may forgive his honor, as below siman 242, seif 32: "a rabbi who forgives his honor — his honor is forgiven"; but Rambam, chapter 1 of Laws of Shechitah, and Kol Bo wrote the reason that they excommunicated: because he will rely on his shechitah another time and it will be flawed and he will slaughter with it — end of his words. And accordingly, perhaps the sage cannot forgive; however, in the Talmud, chapter 1 of Chullin (daf 10b), it appears like Rashi and Ran, and so is the implication of the poskim.`,
  '17#ב': `<b>And to them the sages forgave, etc.</b> And in Agudah, chapter 1 of Chullin, he wrote another reason: because in our time there are no Torah scholars — for they do not know even tractate Kallah; and so in Maharil's responsum siman 71 and Mahari Weil's responsum siman 163 and Maharik, root 163; and so below siman 242 regarding one who shames — that nowadays all are like ignoramuses; and Rabbenu Yerucham brings it there.`,
  '17#ג': `<b>And much settling of mind is required, etc.</b> See Maharshal, chapter 1 of Chullin siman 39, who greatly challenged the slaughterers of this time who check the knife hastily and without intent of heart, and that one should warn and be strict with them in this matter — see there.`,
  '18#_': `<b>So that he not come to be lenient, etc.</b> And in Rivash he wrote that also the korkeshot that they take from the kosher alone — it is forbidden to take them for this reason; and Darkei Moshe brings it; and even though in Choshen Mishpat siman 306, seif 4, Rabbenu Yerucham wrote that butchers who take korkeshot from the kosher are called proper wages, and if they became neveilah they must pay — and these are Tur's words there: "and even though they do not take anything from treifot, since if it had not become treifah he would have taken — behold this is his wages; and also the korkeshot that they give him from the kosher — they themselves are his wages also for the treifot" — there it deals where the custom is thus, even though it is not correct, as he challenged; also Rambam on the custom that was in his time, that they took wages only from the kosher alone, as in Rivash; or Rabbenu Yerucham holds that when he takes korkeshot it is permitted for him to take from the kosher alone, for we cannot say he will come to be lenient in order to take korkeshot — for we do not suspect him that he will eat treifot, and if so he will have to sell them and fears lest they perceive that he does not eat them and sells them; but when he takes other wages it is forbidden; and perhaps from this the custom spread in some places that slaughterers take korkeshot from the kosher and not from treifot, even though it is a bad custom; and so in Hagahot Maimoni, chapter 1 of Avodah Zarah: "and it is difficult — how do the treasurers take from the butchers? For there is suspicion that because of the butchers he permits" — end of his words; and he is Avodah Zarah; and see Maharshal, chapter 1 of Avodah Zarah, seif 8 — he gave a settlement for this custom; and still it requires study in the matter.`,
  '19#_': `<b>His actions prove against him, etc.</b> For certainly when they gave it to Shimon they did not give it to him to check halfway; and when he saw that he did not check as required, he took it from his hand and went to slaughter — his actions prove against him, etc. — end of Rashba; and see Maharam of Lublin's responsum siman 76.`,
  '20#א': `<b>And he said, this flaw, etc. — they remove him.</b> For he testifies about himself that he is not careful between a flawed knife and one that is not flawed; and furthermore, that he slaughters with a flawed knife l'chatchila — Rashba; and see siman 119.`,
  '20#ב': `<b>The utensils are forbidden.</b> See above siman 1, seif 1, in the gloss.`,
});

// --- turei-zahav (15) ---
patchFile('siman_018/turei-zahav/part-001.txt', 'turei-zahav', {
  '1#_': `<b>Even from the side.</b> And this does not include the markings of the knife that craftsmen make at the time of making the knife, since it is far from the point — so Maharshal.`,
  '2#_': `<b>Provided that it catches in it any amount.</b> In the Gemara many amoraim are cited who were stringent in checking — to check in the sun or in water, for when one passes its point on the water, if there is a flaw in the knife they feel it in the water — and that is even any amount; and Maharshal concludes that it is fitting to be stringent thus, but in the general case it suffices with checking avshara and atufra.`,
  '4#_': `<b>A knife that one checks on holacha, etc.</b> This holacha and hava'ah are not like our holacha and bringing back, where we hold the knife in one hand and its point upward and pass the finger on it — for according to that the matters in this seif would not be understood; rather it deals where he passes the point of the knife on his finger, and so on hava'ah; and in this way one checks the knife, and so it is explained in seif 9 that their checking was in this way; and if so, holacha of checking and holacha of shechitah are one matter. Tur and Rif rule: even in the middle, etc., if the point faces the head, etc.; and Beit Yosef toiled in explaining the matters, and it seems they are as their plain sense: every catching flaw has two points — one toward the head of the knife, namely the upper point, and the second toward the handle, namely the lower point; and on this he said that if the point of the handle side was honed and there is only the upper point, even if it is in the middle of the knife, it is valid on holacha and did not bring back, and so the reverse; and so explained Mahari Chagiz, may his memory be blessed.`,
  '5#_': `<b>All are masuchseches.</b> Tur brought this in the name of Baal HaItur: it deals with catching; and Beit Yosef challenged: if so, even one is invalid; and many answered what they answered; and it seems to me a correct answer: after he analyzed the wording — for they said in the baraita, and Tur cited: "a knife that has many flaws" — judge it like a saw; and why did they not say "invalid"? Rather it appears they taught another law: that we find above siman 6, with a knife whose one side is like a saw, etc., that if he slaughtered on the beautiful side it is valid b'dieved; and the same is a long knife that has a flaw and a measure of shechitah remains, etc., as Rama wrote there — it teaches us: even though if there were only one catching there would be permissibility b'dieved if he slaughtered not opposite the catching, nevertheless if there are two or more there is no permissibility, but it is like a saw — meaning as if the whole is flawed and there is no beautiful part at all; so it is correct according to Baal HaItur; and there is a practical difference for this explanation even for us in this law.`,
  '8#_': `<b>Like a serpent.</b> Kesef Mishneh explains: meaning like a serpent whose spine is curved when it raises its head and tail and between them like a bow. And Mahari Chagiz wrote that it implies specifically low once; and so it appears from Rashi, who wrote: such as where it was flawed with a large flaw and the points were smoothed and the knife is low there — it implies only once — end of his words; and I know no source or hint for this stringency, since there is no flaw on it — what difference to me once or many times; and also Shulchan Aruch's wording, which is Rambam's language, indicates this, for he wrote "a knife that rises and falls" — it implies the whole knife is thus; for otherwise he should have said "a knife in which there is rise and fall"; rather the whole knife is so — end of his words; I say that no one is concerned for this stringency.`,
  '9#_': `<b>Avshara.</b> Opposite the esophagus; and atufra opposite the trachea — for whatever these do not feel, also the esophagus and trachea will not feel a flaw — so Tosafot.`,
  '11#א': `<b>Many animals.</b> The same applies to one animal — checking is required after shechitah lest it was flawed in the hide; rather it teaches here that there is prohibition even with many animals.`,
  '11#ב': `<b>And one who wishes to bring himself, etc.</b> Levush wrote: one who slaughters for others and afterward a flaw is found — he is liable to pay all the loss, for he is a damager with his hands — end of his words. And it is not clear to me, for it is in Bava Kamma (daf 99): that hide which came before Rav — it explains one who slaughtered his fellow's animal in a matter where the cause was for the rabbis and for R' Yosi it is valid, and Rav ruled treifah and exempted the slaughterer from paying because of doubt of theft — perhaps he holds like R' Yosi that it is valid; and so Tosafot, that Rav had a doubt in this; if so, why not say also there that the slaughterer was negligent by bringing himself into doubt against the rabbis, and certainly they would declare treifah for him? Rather, even so, since there is reason to rule like R' Yosi, one does not take money from his hand; all the more so here, where he thought there would be no treifot at all — certainly one does not take from him, for perhaps on the second joint-bone it was flawed; and against what is written in Choshen Mishpat siman 307, that a butcher is liable when it became neveilah for certain — but if the knife was found flawed and he checked it first, since we can say on the joint-bone it was flawed, we do not take money from doubt — end of his words; from this we learn: if he did not check, he is liable — this case is different, for it deals with the first checking that is required for everyone, and there is no doubt that he brought himself in first; therefore certainly he was negligent by not doing as required, for which he is liable; not so between shechitah and shechitah, which is only ordinary diligence, as Beit Yosef in the name of Baal HaMaor and Rashba, and so is Maharai's view here, that Rama wrote in his name that he may bring himself into doubt; certainly it is better than that hide of Rav that we mentioned; and furthermore, how is gerama relevant here? For Terumat HaDeshen siman 215 wrote that gerama is specifically where there are words of damage, or damage was done immediately; and therefore he exempted one who incited a dog against his fellow, because the damage was done after the incitement — all the more so here, where there is no treifah except from doubt — end of his words; one does not take money from this at all. And even though Terumat HaDeshen siman 186 wrote that for all stringencies that we practice, even though by law it is permitted, such as a slight shehiyah — nevertheless, since it is publicized as forbidden, the slaughterer is liable in wages to pay — it is not similar to this, for there the damage is certain, since you know it will become treifah by this; but here the damage is not certain at the time of the act, as above.`,
  '12#_': `<b>And if he touched the joint-bone, etc.</b> For from reasoning the joint-bone makes a flaw more than the hide — end of his words; we do not forbid the first, since he checked first; we do not establish unseemliness because of the hide, but because of the joint-bone that we saw he touched, and bone is accustomed to flaw; therefore they say for stringency to forbid the others.`,
  '13#_': `<b>Since it went out in permissibility, etc.</b> With this is resolved what is difficult from seif 15, which wrote "but from doubt we do not attribute," etc., and here we are lenient in doubt; and so from seif 16, which ruled specifically when he checked the knife after shechitah they say perhaps he broke bones, and here they say to him even if he did not check after shechitah. And indeed all is settled: certainly in the whole Torah we follow presumption unless the matter is before us to check — then we do not rely on presumption, as Mordechai, beginning of Chullin, in the name of R' Yehudah HaLevi, regarding majority present at shechitah are experts — if it is before us we do not rely on the majority; and so here with the knife: whatever is before us we are obligated to check; and so Ran explicitly with these matters, chapter 1 of Chullin; and perforce, whoever did not check — the presumption of the knife that it was good at the time of shechitah, since he checked before, nevertheless he is now obligated to check again; therefore in that of seif 15 and seif 16, where the knife was not lost — perforce he must check, and whoever did not check has no good presumption and never had a time of fitness; if he had come to ask before this doubt arose that it is now found flawed, we would not have ruled permissibility, and there is no time for permissibility here — one should be stringent from doubt as if there is no presumption; not so here, where the knife was lost and then it had a good presumption, and if he had come to ask that time we would have ruled permissibility — it turns out there was time for permissibility; therefore we say that even when found afterward and it is flawed, since it is possible it was flawed after shechitah and it already had permissibility if he had come to ask, the doubt does not forbid afterward; it turns out everything is correct. And so Maharshal ruled these laws as mentioned in Shulchan Aruch; and Mahari Chagiz was challenged: what do we care about "since it went out in permissibility" — if it was forbidden from the outset by law, what do we care that it went out in permissibility? Rather certainly the reason for permissibility here is because an additional doubt was added to be lenient after shechitah, since the knife was lost — perforce also in seif 15 one should be lenient wherever we saw it fell, even if we did not see it fell on its point; and perforce he wrote that one who permits in that of seif 13 permits even in the doubt of seif 15; and he wrote that it is an error before the rulers to permit here and forbid in the doubt of seif 15; to me their words seem correct, for the matter depends on presumption — and this is what we said: "since it went out in permissibility," meaning the doubt arose after the knife had a good presumption and ruling for permissibility; and the rulers' words are clear.`,
  '15#א': `<b>But from doubt, etc.</b> Explained in seif 13.`,
  '15#ב': `<b>Even by way of breaking.</b> I hope I see here that his words are wondrous — they follow Ran, chapter 1 of Chullin; and thus: and there is in this a leniency — that if he slaughtered one animal and touched its joint-bone and a flaw was found, his shechitah is valid, for when he broke bones it is similar; and it is reasonable that we cannot rely on this leniency, since the halachah was not decided like Rav Chisda except when he broke — one may not be lenient thus unless he broke the bone entirely; but not by touch — and so is Ramban's view; and others are further stringent to say that even if he broke the joint-bone itself, his shechitah is invalid; and it is possible to explain "he broke bones" — the joint-bone is soft; and furthermore, even other bones that if he broke them like the joint-bone bone we do not attribute — specifically breaking they say; but cutting by holacha u'va as he does with the joint-bone — not; and so is Rashba's view — end of his words. Behold the rabbi, author of Shulchan Aruch, understood what Ran wrote and "others are stringent" — even if he broke the joint-bone itself means even by way of breaking, namely by striking, not by holacha u'va; and perforce he ruled here: even by way of breaking it is forbidden. The examiner will see with his eyes that Ran did not intend this, for he had not yet mentioned anything of the distinction between striking or holacha u'va until he wrote afterward; and furthermore, "even if he broke other," etc. — he then invented this distinction; and since way of breaking is permitted even according to the third view, all the more according to the second; rather simply what Ran said first, that even if he broke the joint-bone itself, means by holacha u'va. Rather he comes to exclude mere touch, where at first he did no breaking in his cutting; but even if he did actual breaking in his cutting and something was missing in the place of the cut — nevertheless we do not attribute, for two reasons: one, that it is soft and that cut does not spoil the knife; and furthermore, even if it were hard like other bones, we do not attribute, since the cutting was done by holacha u'va — the knife is not spoiled thereby, even with other bones; but never if he struck forcefully on the joint-bone, not by holacha u'va — it is obvious we attribute, and it is included in "he broke bones in it," meaning all bones; and why did they not say except the joint-bone? Rather it is clear they did not exclude except that which is by holacha u'va as his way of cutting the joint-bone after shechitah; but they do not exclude striking at all in any bone. And clear proof further: for Ran wrote that so Rashba wrote; and behold Rashba himself wrote in his long Terumat HaDeshen, end of gate 2: "because the way of the joint-bone is not made to be flawed by holacha u'va," etc. — it implies; but not by holacha u'va we attribute even in the joint-bone, which is made to flaw. And furthermore, what is worse than falling on hard ground, that he permits here when it fell on its point — all the more on the joint-bone. And furthermore, we find in Mordechai in the name of Rivak, who was accustomed to strike the knife on wood before hiding it so that afterward he could attribute — behold our eyes see that certainly the joint-bone is harder than wood; and what reason not to attribute if it is by striking that he struck, not by holacha u'va — as above, so it is correct; and so is Tur's conclusion in the name of HaItur, who wrote: since the way of shechitah is flawed — it is not explained "he broke bones"; it implies: if not by way of shechitah but by way of striking, we properly attribute — end of his words; it appears to me the rabbi's words in Shulchan Aruch are wondrous in this.`,
  '16#_': `<b>And afterward it was found flawed.</b> See what is written in seif 13 from this.`,
  '18#א': `<b>The butcher must take, etc.</b> In Choshen Mishpat siman 306 Tur wrote: butchers who take korkeshot from the kosher are called proper wages, even though they take nothing from treifot — end of his words; it implies that even in our rabbi Tur's days they practiced taking from the kosher alone; and on this basis it is determined today as well. And the reason seems that they were not suspected for such a small matter to feed treifot; and it is not similar to that of Ila in Yavneh, chapter Ad Kamah, regarding permissibility of firstborns, where there is suspicion for a great matter — so it appears to settle the custom; and I again found thus in Maharshal.`,
  '18#ב': `<b>And therefore they practiced, etc.</b> It implies; but by law one slaughters and checks for himself — and it is difficult from the mishnah (chapter 2 of Negaim): all firstlings a person may inspect except his own firstlings; and Rosh already challenged there many things that we find a Torah scholar may rule for himself; and he concludes there: specifically where prohibition was established he may not rule for himself; and if so, here too regarding checking it is fine that it was permitted, but shechitah would be prohibition by law, for while alive it stands in presumption of prohibition; and it appears that by law it is not permitted except to slaughter, for majority present, etc.; but if a ruling occurred to him he should not rule; and see what is written siman 312.`,
});

// --- beer-hagolah (20) ---
patchFile('siman_018/beer-hagolah/part-001.txt', 'beer-hagolah', {
  '1#_': `Conclusion of the Gemara, Chullin daf 18, and like Rav Huna.`,
  '2#_': `From the implication of the Gemara there.`,
  '3#_': `Tur in the name of Rambam, chapter 1 of Laws of Shechitah; and Rashba wrote in Terumat HaDeshen that such is Rif's view; and so Ran; and see seif kaf 4.`,
  '4#_': `There in the name of Rashba; and so Ran. (°) Explanation: language of catching in summer heat — that it gathers a hair's-breadth between its two points, and it is less than catching a fingernail.`,
  '5#_': `Statement of Rav Chisda there, daf 17.`,
  '6#_': `From the incident before Rava bar Chinena there, daf 18.`,
  '7#_': `Baraita there, and as R' Elazar and Rava explain in the Gemara there; and Rambam's language, chapter 1 of Laws of Shechitah, law 15.`,
  '8#_': `Mordechai in the name of Rif and Kol Bo and Hagahot Maimonit and Semak and Agudah.`,
  '9#_': `Baraita there.`,
  '10#_': `Question there from Rav Ashi, and the conclusion is for permissibility.`,
  '11#_': `Statement of Rava there.`,
  '12#_': `Statement of Rava there, daf 17 (and Rambam's wording there).`,
  '13#_': `Statement of Rav Papa there and several amoraim who hold thus. (°) And the reason of avshara: because the esophagus is soft; and atufra: because the trachea is hard.`,
  '14#_': `Tur.`,
  '15#_': `Kol Bo in the name of Raavad.`,
  '16#_': `Rashi in Chullin daf 16 and Rosh there.`,
  '17#_': `Rosh there and Shaarei Dura.`,
  '18#_': `Beit Yosef.`,
  '19#_': `From the incident of Rav Yosef and the final wording of Rav Huna for stringency — Rif and Rosh and Rambam, chapter 1 of Laws of Shechitah, and Rashba in Terumat HaDeshen and Baal HaItur.`,
  '20#_': `Rosh and Rambam there and Rashba in Terumat HaDeshen.`,
});

// --- baer-heitev (27) ---
patchFile('siman_018/baer-heitev/part-001.txt', 'baer-heitev', {
  '1#א': `<b>The side.</b> And Taz wrote that this does not include the markings on the knife that craftsmen make when making the knife, since it is far from the point.`,
  '1#ב': `<b>Neveilah.</b> And Shach explains: it is doubtful neveilah, for we are concerned lest it was flawed in the hide.`,
  '1#ג': `<b>Flawed.</b> And the reason: an animal while alive stands in presumption of prohibition until you know with what it was slaughtered.`,
  '1#ד': `<b>In fowl.</b> And Shach wrote: even if he also touched the joint-bone — for there are two reasons to be lenient, its measure is soft, and he touched the joint-bone — nevertheless we are concerned lest it was flawed in the hide, and it is doubtful neveilah.`,
  '2#_': `<b>A hair's-breadth.</b> And Taz and Shach explain: l'chatchila we are not concerned for a flaw of any amount, and one need not check except avshara and atufra. We do not need checking in sun or water — when one passes its point on water, if there is a flaw on its point they feel it in water, and that is even any amount — this is not required l'chatchila; but if afterward a flaw of any amount is found, it is treifah — end of his words.`,
  '3#_': `<b>He may not slaughter.</b> And Shach explains: he may not rely on checking at the end, lest he forget to check, and he is like one eating neveilah. And he asked: why do we not bless on checking the knife? Perhaps he will reconsider and not slaughter.`,
  '4#א': `<b>On holacha.</b> Meaning: he passes the knife on the finger; and so on hava'ah — Taz. And now they practice passing the finger on the knife — and this too is correct — Peri Chadash.`,
  '4#ב': `<b>Invalid.</b> And the reason: anything not dependent on a person, he is not aware; and we are concerned lest the point strike the siman and tear it.`,
  '4#ג': `<b>Everything.</b> And Shach wrote: even masuchseches from the side one should declare treifah, since we are not expert — we are concerned lest it not stand at the head of the knife, and the hide and flesh are weakened by the head of the knife, and afterward it is torn by the point.`,
  '5#_': `<b>He did not feel.</b> And Taz wrote: even though we hold above siman 6, with a long knife that has flaws and a measure of shechitah remains, it is kosher if he slaughtered not opposite the flaw — nevertheless, if there were two flaws or more, there is no permissibility, but it is as if the whole is flawed. The flaw has no measure: whatever is felt on flesh or fingernail, even if they do not enter within at all — behold it is a flaw and invalidates according to all — language of the rabbis, authors of Beit Yosef and Bach, on Tur's words at the beginning of siman 18; and see Sefer HaZichronot.`,
  '7#_': `<b>Treifah.</b> And Shach explains: to exclude if there was not shehiyah of the measure of shehiyah between siman and siman; or where he intended and placed the two simanim together one next to the other and slaughtered both — then even in an animal it is kosher; however, certainly l'chatchila one should not slaughter with it even fowl, since l'chatchila one must slaughter two simanim in fowl as in animal; and see below siman 23.`,
  '8#א': `<b>Like a serpent.</b> And Taz explains: its spine is curved when it raises head and tail and between them like a bow.`,
  '8#ב': `<b>L'chatchila.</b> Taz and Shach wrote that even two or three rises and falls are also kosher, not like Bach; but in Beit Yosef he wrote that in our time one does not slaughter with it except in a time of distress, but with two rises and falls it is not permitted even in a time of distress.`,
  '9#א': `<b>At all.</b> And the reason is in Taz: avshara is opposite the esophagus, and atufra opposite the trachea.`,
  '9#ב': `<b>The fingernail.</b> And Shach wrote that one should also rinse the knife before checking, because blood sometimes congeals in the checking; and Raavad testified that such happened to him — he checked and did not find a flaw, and afterward when he rinsed in water he found a flaw — end of his words. If he did not check the knife except its point alone and not the sides, and the knife was lost — even if he slaughtered with it many animals, kosher ones, as in Shulchan Aruch daf 22; and it is permitted to check with whatever finger he wishes — Darkei Shalom siman 4. And according to Perishah he wrote that one checks only on the thumb, which is long — Peri Chadash wrote: also moisten the fingernail with a little saliva, for signs in the life of the animal are also moist — even though one feels more without saliva.`,
  '10#_': `<b>With it.</b> And Shach wrote: but b'dieved it is permitted if he said, "It is clear to me that I did not touch the flaw"; and this is specifically when he knew before shechitah that there was a flaw in it; but if he did not know and said, "It is clear to me that I did not touch," such as where the flaw is above its middle — even b'dieved it is forbidden, for anything not dependent on a person, he is not aware.`,
  '11#א': `<b>And each one.</b> Shach's explanation: proper checking — avshara, atufra; and we do not say it is an interruption between blessing and second shechitah, for needs of shechitah are not an interruption, as below siman 19. And not specifically many animals — one animal too requires checking after shechitah, lest it was flawed in the hide.`,
  '11#ב': `<b>For shechitah.</b> And Levush wrote: if he slaughters for others and did so without permission — he must pay, even if he slaughters for free, as the law of a damager with his hands; and see Choshen Mishpat siman 306. But Taz disagrees and ruled he need not pay, for perhaps on the joint-bone it was flawed; but if he did not check even on the first, which is required for everyone — certainly he was negligent and must pay; not so between shechitah and shechitah, which is only ordinary diligence — if he brought himself into doubt he is certainly exempt from paying — see there; and in Sefer Nehar Shalom he disagrees.`,
  '13#_': `<b>We establish it.</b> However, if the knife is before us, one must check, and presumption does not help at all.`,
  '14#_': `<b>So that it not be flawed.</b> Lest he slaughter without checking and the knife be lost and we rely on its presumption that it was checked before.`,
  '15#א': `<b>Its point.</b> And the reason is in Taz and Shach: because there is a double doubt for prohibition — one, that perhaps it did not fall on its point; and even if you say it fell on its point, perhaps it was not flawed on the ground, for ground does not certainly flaw; and it is not at all similar to above seif 13, where the knife was lost and afterward found flawed, that it is valid — there there is only one doubt, that perhaps he broke bones and was not aware; and furthermore, here, since the knife is before us and checking is required, it has not gone out ever in presumption of permissibility; but there, since it was lost, it went out in presumption of permissibility.`,
  '15#ב': `<b>Soft.</b> Taz and Shach disagree on this; and they wrote: even on the joint-bone, if he struck not by way of shechitah but by way of striking not by holacha u'va — one may attribute, for it is no worse than hard ground.`,
  '16#_': `<b>And he was not aware.</b> And Shach wrote: here the Mechaber wrote two reasons; and above seif 13 he wrote only the reason that we say he broke bones alone, because above it deals where it is not known whether he broke bones or not; but here he informs us: even though it is known clearly that he did not break bones, such as where he placed it in a box — nevertheless, since he checked after shechitah, say it was flawed by something else by itself; and even though in seif 14 we hold we are not concerned lest with its standing it was flawed — there, because unseemliness is not before us, we establish its presumption; but here, behold the flaw is before you.`,
  '17#_': `<b>To excommunicate him.</b> And Shach wrote: according to Rambam he cannot forgive; and Agudah wrote: nowadays in our poverty there are no Torah scholars — for even in tractate Kallah he does not know — and certainly forgiving their honor; and so Rama below siman 245.`,
  '18#א': `<b>The kosher.</b> And Taz wrote: in Choshen Mishpat siman 306 the Mechaber wrote: butchers who take korkeshot from the kosher are called proper wages, even though they take nothing from treifot; and from this reason Taz ruled that one should permit where the custom is thus; and he wrote they were not suspected for such a small matter to feed treifot. And Rivash disagrees and wrote one should not distinguish great benefit from small benefit — always there is suspicion; and Shach wrote permissibility for another reason: we certainly do not suspect he will eat treifot, and if so he will have to sell them and fears lest they perceive — nevertheless he wrote one should abolish this custom. A slaughterer and checker who set a dinar for him between kosher and treifah, and after he declared one animal kosher he returned and said it is treifah and gave an excuse — one should believe him — Darkei Shalom siman 122. A community that accepted a slaughterer for wages that from every animal of Israel they will give him the tongue, and the kitchen is with a non-Jew — now the non-Jew slaughtered animals with Israel in partnership — if Israel must give the tongue, see Terumat HaDeshen siman 57. One who converted and returned in complete repentance may be slaughterer-checker as Nehar Shalom in the name of Rosh.`,
  '18#ב': `<b>The community.</b> And specifically one who slaughters and sells to others; but if he slaughtered for his need and not to sell to others — it is plainly permitted — Beit Yosef. And Taz wrote: from Rama's words it implies specifically from the side of custom it is forbidden, but by law certainly permitted; but in my humble opinion it seems one should forbid by law; and in any case by law it is not permitted except to slaughter — majority present, etc.; but if a ruling occurred he should not rule — end of his words; and he did not see Tosafot's words, Niddah daf 20b, s.v. kol yoma.`,
  '20#_': `<b>Forbidden.</b> For he slaughtered with a flawed knife l'chatchila. A butcher who said he checked the knife after shechitah and gave it to one youth to give to another man to slaughter — that man found it flawed, and that youth is an adult and said, "It is clear to me I touched nothing hard, but immediately gave it to the second slaughterer's hand" — and it was found flawed — one may not be lenient to say he is an agent who is not expert; but if the youth is a minor, those animals the first slaughtered remain in presumption of permissibility, for we say certainly he is an agent who is not expert — Peri Chadash from Maharival. He also wrote there seif 9: they asked about one layman who deposited his knife with one man and it was found flawed; on Yom Tov 2 one came who did not know it was flawed and brought the knife to another sage, who declared it fit, and slaughtered with it and hid it; and after about ten hours they found the knife flawed — he ruled all he slaughtered is treifah, for one may not be lenient to say he repaired the knife before the second's shechitah and afterward it was spoiled in those ten hours; and see Peri Chadash there in this siman. A butcher whose knife was found flawed not at the time of shechitah — he is not disqualified, everything according to what kind of person he is — Maharam of Lublin siman 76. A butcher who checked the knife and a flaw was found and he gave to his fellow, who checked and did not feel the flaw, and fed the many — afterward the first revealed the second's disgrace, and that he did not reveal to feed his enemies — the court should fine for this and remove the first butcher — Rashdam siman 47; and see above siman 1 in the gloss.`,
});

// --- beur-hagra (34) ---
patchFile('siman_018/beur-hagra/part-001.txt', 'beur-hagra', {
  '1#א': `<b>Even from the side.</b> See above siman 9 in Shulchan Aruch and gloss for the view of Raavad (Ran brought it).`,
  '1#ב': `<b>Even if he touched, etc.</b> From what they say there: "the bone, certainly," etc., and they conclude: say on the joint-bone bone, etc.; and perforce certainly he touched; and so Mordechai.`,
  '1#ג': `<b>And even in fowl.</b> Rashi there, s.v. halachta.`,
  '2#א': `<b>(Seif 3) The measure, etc.</b> Not like Rav Chisda there — all those in the West and Nehardeans and Rav Sheshet and Rav Ashi do not hold like R' Hoshaya, that all are less than catching a fingernail; and furthermore they said there: it is similar to a thorn — what? And if so, what is the question to him? For it does not catch a fingernail. (Likut) The measure, etc.; and Rosh explains catching the fingernail — that the fingernail feels, as (II Samuel 22:38) "and I girded them from my loins"; and accordingly there is no proof from a thorn, for even a thorn the fingernail feels; and he ruled like Rav Chisda, may his memory be blessed; and my view is to be more stringent than Rashba — end of his words.`,
  '2#ב': `<b>And provided, etc.</b> For we call it catching, and as its name — that it catches something — to exclude that it catches nothing; this is similar to the thorn they said there.`,
  '2#ג': `<b>Even, etc.</b> From Rav Acha bar Yaakov.`,
  '3#_': `<b>(Seif 3) And if he transgressed, etc.</b> From Beit HaGadol; and also from what is written there, R' Chiya: from where, etc. — it is obvious, etc.; and if only before — what is the question, it is obvious.`,
  '4#א': `<b>(Seif 4) A knife, etc.</b> As Rashba explains: at the head of the knife toward the head of the knife; and he holds it does not tear except toward the flaw; and the checking is that he passes the knife on his finger, as written in seif 9. (Likut) A knife, etc.: for this is what is written there: "from two," etc. — weakens: weakens — it cuts the hide and flesh, and the flaw strikes the simanim from one direction, etc.; for it is thought: since it says catching, specifically; masuchseches in all is valid; and they answer: it stands, etc., opposite the head of the knife. Rashba; and this contradicts Rashi's explanation: if at the head of the knife itself, even catching — how is it possible the first flaw cuts hide and flesh? And furthermore, if so, what does it say: "a knife that has many flaws," etc. — perforce the second flaw is not at the head of the knife — if so, with one it is invalid; and so there is no question here that he did holacha, etc., and no question that it stands at the head of the knife. But according to his explanation it must be: it stands, etc., for since he said he did holacha and did not bring back — perforce on the incline toward that side that he did holacha; and so Rif brought only the second establishment. And Rosh and Rosh explain like Rashi — end of his words.`,
  '4#ב': `<b>And this is, etc.</b> For everything, etc.; and see above siman 1, seif nun.`,
  '4#ג': `<b>And some are stringent, etc.</b> As Rashi explains there.`,
  '5#_': `<b>(Seif 5) For since its flaws, etc.</b> Rashba; and this was required for his method.`,
  '10#_': `<b>(Seif 10) A knife that has, etc.</b> We learn from a hand-saw; and as above siman 6, seif 1 — see there.`,
  '11#_': `<b>(Seif 11) And one who wishes, etc.</b> As is written there: "to invalidate the first," etc. — not from the root of the law, no; and they say: checking is required — good advice, as (Gittin 34b) and Tosafot there 3b, s.v. R' Elazar, and see there 36a, s.v. vehaedim, and Maharam Schiff there — R' Gamliel enacted that witnesses sign the get, as Tosafot there: so they need not witnesses of delivery.`,
  '12#א': `<b>(Seif 12) Even though, etc.</b> From Rav Kahana cited above; and one should not distinguish between many or one — Rashi and Rosh.`,
  '12#ב': `<b>(Likut) And this is, etc.</b> From what is written: Rava challenged in support, etc.; and there specifically something intervening was found, and it says there Hagah: it was born, etc. What is B. And furthermore from what they say: 3:2 checks the knife, etc., and if he slaughtered, etc. — evidently whoever checked first need not check at the end; and even for R' Hoshaya, for Rava holds like R' Hoshaya there — Rava challenged, etc.; and all the more for R' Chiya — end of his words.`,
  '12#ג': `<b>But if, etc. And even if he slaughtered, etc.</b> From what they say: like Rav Huna; and to invalidate the first; and there is no question to validate the first — from this we learn that without this it is valid. (Likut) And even if he slaughtered, etc.: as is written; and if you say: always like R' Hoshaya, etc., from when they attribute, etc.; and the same for us when it was lost; and Rashi there, s.v. lemeifsal, etc., and even though, etc. — end of his words.`,
  '12#ד': `<b>And if, etc.</b> Even though we do not hold like R' Chiya that the joint-bone, etc. — this is for leniency, as they challenged there from a mikveh; and we do not distinguish between a deteriorated knife or animal. (Likut) And if he touched, etc.: so he concludes in Terumat HaDeshen; and see there many views — end of his words.`,
  '13#א': `<b>(Seif 13) Since it went out in permissibility.</b> As written in seif 12.`,
  '13#ב': `<b>And this that was found, etc.</b> As Rosh wrote: behold slaughtered before you; and they say to him: behold unseemliness was born in it, for behold it went out in permissibility; and Taz; and Peri Chadash agreed with Bach — see there.`,
  '14#א': `<b>If he did not check, etc.</b> As is written: animal while alive, etc., until you know with what it was slaughtered — he was precise: with what it was slaughtered. (Likut) If he did not check, etc.: from what is written: 50, R' Elazar — all, etc., for appetite; and like Rava, etc.; and all who slaughtered on it, etc., lest with a flawed knife, etc.; and even though he does not leave the permissible, because ordinary knives are not good — forbidden even b'dieved — end of his words.`,
  '14#ב': `<b>In what case, etc.</b> On Rashi there 8:2, s.v. one who slaughters, etc., and sometimes, etc. — it implies; but now that he slaughtered without checking there is no prohibition. (Likut) In what case, etc.: from what is written 8:2: the butcher needs, etc.; one who slaughters, etc. — it should surprise me: why need a special knife for shechitah? For checking is required before shechitah; and it is reasonable there is a difference that checking is not required when he returns and slaughters; and if he slaughtered and did not check and the knife was lost — his shechitah is valid, for establish the knife on its presumption, etc. — see there — end of his words.`,
  '14#ג': `<b>And it is fitting, etc.</b> As is written in the Gemara; and Rashi there; and in chapter 9 of Bava Metzia: resting knife, etc., since it is flawed, etc.; and Rashba explains: shechitah knife; and so in chapter 123 of Shabbat (123b).`,
  '14#ד': `<b>And nevertheless, etc.</b> As is written (9:1, 32a): in order that the butcher examine, etc.; and other places, even though they required three knives.`,
  '15#א': `<b>By way of breaking.</b> As is written: he broke, etc.`,
  '15#ב': `<b>And specifically when we saw, etc.</b> As is written there: animal while alive, etc.`,
  '15#ג': `<b>And if, etc.</b> As is written: he broke bones in it — specifically bones.`,
  '15#ד': `<b>And there is no distinction, etc.</b> As above in the previous seif.`,
  '16#_': `<b>If he checked, etc.</b> Greater than this — seif 13.`,
  '17#א': `<b>And if it was found, etc.</b> Gemara there.`,
  '17#ב': `<b>And when it was found good, etc.</b> On Rashi there, s.v. his knife was found, etc.; and as is written 10:2, 17:2: they did not say, etc.; and they say in chapter 1 of Kiddushin (32): a rabbi who forgives, etc.`,
  '17#ג': `<b>And nowadays, etc. And to them, etc.</b> As above.`,
  '17#ד': `<b>And the quality of, etc.</b> According to chapter 8 of Shabbat 1 (in the incident of Rava there, who set his heart to the teaching until he did not feel like his father felt his fingers).`,
  '19#_': `<b>And therefore, etc.</b> As is written in seif 17: when a flaw is found they remove him; and it implies even the first time; and so a butcher after whom fat like a se'ah was found (Pesachim 93b) — there.`,
  '20#_': `<b>A butcher, etc. And when I, etc.</b> For it is forbidden even in such case, as written in seif 10; and furthermore it is not correct to use a shechitah knife — as above seif 14; and see there siman 420.`,
});

// --- kereti (28) ---
patchFile('siman_018/kereti/part-001.txt', 'kereti', {
  '1#א': `Behold it is neveilah — meaning doubtful neveilah; and so Rambam explicitly; and so Shach; and see what I clarified above siman 1 at length, to distinguish between a mikveh that was measured and found lacking, that we declare treifah retroactively for certain and not doubt — see there.`,
  '1#ב': `We are concerned: an animal while alive stands in presumption of prohibition; and if there is doubt in shechitah — establish the animal on its presumption, and it is forbidden.`,
  '1#ג': `Even in fowl — its measure is soft; and it is hard in reality to make a flaw; nevertheless we are stringent; and Bach wrote: even if he touched the joint-bone. And it seems: even if he slaughtered only the trachea — there is a good doubt: perhaps afterward it was flawed; and even if you say from before: perhaps he touched the flaw before he slaughtered half the trachea — if so the flaw does not flaw; nevertheless it is forbidden, for any doubt in shechitah is forbidden.`,
  '2#א': `Measure of flaw — any amount; see Shach, who wrote even less than catching a fingernail; and that we require fingernail checking — we are not concerned for small flaws, and ordinarily they catch on the fingernail; but in truth if they are smaller we forbid; and so Maharshal and Bach — his view is to declare fit if the flaw is smaller than catching a fingernail; and acharonim disagree; and see Peleti: at first my view agreed with Bach that if he slaughtered only the trachea certainly correct with Bach that if it does not catch on the fingernail it is valid — and with this I settled Rambam's contradiction; but finally I brought that any flaw that is felt is treifah by law, and one may not be lenient at all, and everything is called catching a fingernail.`,
  '2#ב': `Any amount — in Lechem HaPanim he gave a taste for a flaw according to a secret that the soul dwells in it — see there; and his silence is better than his speech, Heaven forbid to give a taste for God's mitzvot; and so was the law according to Maharam; and there is no point, for in tastes one gives a stumbling block in error, because many do not hear that secret voice, and Torah provides leniency in these laws.`,
  '2#ג': `Even a hair's-breadth — and in error many are lenient and say of the knife that it is not a flaw but in Ashkenaz tongue "ruvikh," and it is for lack of their feeling and knowledge, for ruvikh is small flaws felt with great attention; and one who slaughtered with a knife that is ruvikh is wicked and feeds treifot to Israel in error; and one should excommunicate that this name ruvikh not be mentioned or counted — and it is a complete flaw.`,
  '3#_': `One must check, etc.; and certainly if there is no knife in presumption of being checked at all — it is plain he may not slaughter with it, for he slaughters treifah; and if he relies he will check afterward — forbidden, lest he forget to check and commits a prohibition. But in a knife in presumption of being checked — nevertheless one must check it before shechitah and not rely on its presumption; and on this Perishah teaches: he made Scripture support: "you shall not eat upon the blood" — for one not checked at all a verse is not needed.`,
  '4#_': `His shechitah is invalid — since he did not know, he was not careful, it was not dependent on him, and he was not aware.`,
  '5#_': `Even if all are masuchseches — learn from Gemara: a knife that has many flaws — judge it like a saw; and they are in masuchseches; for if in catching — what difference if many flaws or one? One inhibits shechitah. And Taz explains in the name of Baal HaItur: it deals with catching; nevertheless there is a difference: even on the beautiful side one may not slaughter, since there are many — it is like a saw; even the beautiful part is invalid.`,
  '7#_': `A knife whose edge is smooth — see below siman 23, for there is its true place.`,
  '8#_': `L'chatchila — even several rises and falls — nevertheless kosher — Shach.`,
  '9#_': `And he must shift the fingernail; also one must rinse the knife, for sometimes a drop of blood is on the knife and thus a flaw is not felt.`,
  '10#א': `Even if he intends, etc.; and if he says, "It is clear to me I did not touch the flaw" — if he knew there was a flaw, it is permitted; if not, forbidden, for anything not dependent on himself, etc. — Shach.`,
  '10#ב': `One must check in all details of checking — twelve checkings customary, etc.; and with all this it is not an interruption between blessing of shechitah and slaughtering all animals, for all are needs of shechitah; it is not an interruption.`,
  '11#א': `And even the first — lest in the hide of the first it was flawed; for animal while alive stands in presumption of prohibition.`,
  '11#ב': `To bring himself into doubt — and nevertheless forbidden because of bal teshachet where the meat is treifah less than the value of kosher — see Peleti.`,
  '11#ג': `In this doubt: and if he slaughtered for others and did not check between shechitah and shechitah, and afterward a flaw was found — opinion of Taz: the slaughterer must pay, for he was negligent; and Taz's view: exempt; and Shach in Nehar Shalom attacked him; and see Peleti, where I clarified the law is with Taz and the rabbi, may his memory be blessed, wrote. However, he commits a prohibition and does not do well with his people — only gerama in damages we hold forbidden even though there is no liability to pay. And if the court sees he is accustomed to this, and this is a sign he is light-minded — it is fitting to obligate him to pay to fence the matter. And behold in error where they slaughter korbanot and the people hurry to bring — they hurry the slaughterer, for from him people eat at noon; because of this the slaughterer has no leisure to check the knife properly between shechitah and shechitah, and slaughters many fowl one after another without checking in between; and if afterward his knife is found flawed — behold all are treifah retroactively — and who will pay? Many enter and leave; and so in error the stumbling block is before you — many concerns; and on the fast of the chosen day they bring themselves into enormous doubts; and it would have been better not to eat at all. How many times I warned: better to do like the order of the village, but without rushing shechitah until leisure for the slaughterer to slaughter calmly and with settling; even though the Ari, may his memory be blessed, warns to hurry shechitah — he did not speak where there is concern of doubt of prohibition. And if so, all who stand to slaughter are like slaughtered; and if he prepares for shechitah only the delay from overloading the slaughterer — behold he does his work above to sweeten the gevurot as if slaughtered and standing — the Merciful will come in his request; and especially when intent is for Heaven's sake, as written. And in any case the rabbi teacher should supervise this on slaughterers on the chosen day, lest they break through and lighten their head in knife checking and checking simanim, etc., for the great toil of their work; and the wages of fowl slaughterers mentioned will go for atonement in their loss in error.`,
  '12#_': `And if he touched the joint-bone — more common is flaw on joint-bone than flaw by simple hide — acharonim.`,
  '13#_': `His shechitah is valid — acharonim; Taz and Shach lengthened on this from below seif 15: if it is not known it fell on its point to ground — forbidden from doubt; and they raised the matters that here, since it was lost, the matter already went out in permissibility; and see Peleti, where I wrote one may question from sugya of Gemara; therefore I wrote to distinguish in seif 15: there is only this doubt, that perhaps it fell on its point to earth — aside from this there is no doubt that the knife is in presumption of being guarded; not so here, where the knife is not in presumption of being guarded, for it was lost — and there is a good doubt how the flawed knife happened; therefore it is permitted.`,
  '14#א': `His shechitah is valid; and we are not concerned lest when the knife stood a flaw happened, since he did nothing with the knife; however slaughterers say and testify: if the knife stands a while by itself a flaw will happen to it. And in truth in Mordechai and his colleagues only a day or two are mentioned, not more; and in truth one should be stringent if it stood a long time to require checking; but a day or two we have no concern; Yom Tov for two days of exile proves.`,
  '14#ב': `And he should hide it, etc.: lest he use it and flaw it, and he forget and slaughter with it and the knife be lost and be in presumption of checked and kosher; and in truth he used it and made it flawed — Rashba.`,
  '15#_': `Even by way of breaking — and acharonim disagree; and its view: way of breaking to attribute; and I say that before me such an incident occurred, where he struck forcefully on the joint-bone because the minister was forced to take the head and struck forcefully on the joint-bone so the butcher could take it; and afterward he checked the knife and a flaw was found — it was hard for me to rule against Shulchan Aruch; I commanded to hone the knife without flaw and strike twice forcefully on the joint-bone bone, and see if there will be a flaw — behold it is not soft; and that knife accepts flaw. And if not — Shulchan Aruch's words are clear; he struck and a flaw was found — I declared fit according to acharonim.`,
  '17#א': `He showed the knife to a sage — see Peleti, where I wrote in chapter 1; and in ordinary reading one need not show to a sage at all — see there.`,
  '17#ב': `They excommunicate him — because he flawed the honor of a Torah scholar.`,
  '17#ג': `The sage may forgive — see Shach, who wrote: according to Rambam he may not forgive, only when the slaughterer was established as expert slaughterer; but otherwise there is no authority to forgive; and see Peleti.`,
  '17#ד': `And to them the sages forgave — and they gave another reason in settling Rambam's words: we have no Torah scholar present in error — yesterday they were given and we do not know in error; and all this according to what they said: he must show to a sage because of the sage's honor, and there are no sages in our generation worthy to share this honor; but according to Rambam, to separate from prohibition — if he slaughtered between himself and himself, perhaps he will slaughter with a flawed knife — even in this time it applies; and what that they do not know tractate Kallah. And it seems practiced without slaughtering without receipt from a sage — if so we granted and we pardoned; for he authorized him to slaughter without any person and to set the knife; therefore these are the things I wrote in siman 1: one needs receipt specifically from the rabbi teacher, not from slaughterers even if experts, for they cannot forgive the teacher's honor.`,
  '18#א': `So that he not come to be lenient — acharonim wondered at the custom that slaughterers take wages in korkeshot from kosher and not from treifot; ancient custom was in Tur's time, as appears from him, Choshen Mishpat siman 306; and in Avodah Zarah's time before Tur there was a directive on slaughterers — see gloss, chapter 1 of Avodah Zarah; and acharonim toiled to settle the custom. And it seems to me from this the custom spread: certainly one individual slaughters an animal, and if it becomes treifah he will not slaughter more — then there is concern he will be lenient to receive korkeshot; if it becomes treifah he loses; but the custom was established in walled cities that must support the city in meat so meat not lack for every meat-asker; and if there will be treifot in this animal he will hurry to slaughter another to prepare meat for God's people; and what benefit to the slaughterer if he declares this animal treifah — he slaughters another until there is kosher and takes korkeshot from it; and if the first becomes kosher he will not slaughter more — what profit and what loss if he declares fit or invalid? And if one can depict that sometimes the hour presses and they will not multiply slaughter and he may lose korkeshot for this — they did not fix at all, and it is plain. And to be concerned: since through receiving korkeshot, etc., damage is done and he will have to pay if he paused, etc. — this is not common and we are not concerned.`,
  '18#ב': `That a person does not slaughter for himself — and Taz was precise from what is written in Negaim: one does not see one's own afflictions, etc.; and in truth since majority present at shechitah are experts, they permitted; and a Torah scholar is certainly permitted to slaughter for himself, as they say, chapter HaDar: a Torah scholar may rule for himself — Rashi: when he slaughters for himself; and with a Torah scholar there is no concern; but with one who is not a Torah scholar one should protest without slaughtering for himself in any case.`,
});

// --- peleti (6) ---
patchFile('siman_018/peleti/part-001.txt', 'peleti', {
  '2#_': `Measure of flaw — any amount; and catching a fingernail was not mentioned; and Shach wrote in the name of Maharshal: even if it does not catch the fingernail, nevertheless treifah — only ordinarily we are not concerned for such a small flaw; and he attacked Bach who declares fit a small flaw. And Peri Chadash lengthened on this; and with all the length I found no rest; and the essence of the difficulty: all foundation of Rashba and Tur — Rambam did not mention that it must catch a fingernail; and from this they exempted a flaw of any amount from treifah; and he in chapter 1 of Laws of Beit HaBechirah wrote: altar flaw — measure of catching fingernail — and that invalidates a shechitah knife; and if so, apparently Rambam's words contradict; and what appeared at first — we would say that catching fingernail suffices when slaughtering only trachea in fowl, since a flaw has no power due to small size to catch and inhibit the fingernail — also trachea is not inhibited, for no harm happens to trachea from smallness of flaw, and permitted to slaughter with it; but to slaughter esophagus, which is soft — a small flaw of any amount cannot catch the fingernail and passes over it but inhibits and uproots the esophagus; therefore even any amount inhibits; therefore in Laws of Shechitah Rambam wrote plainly: slaughtered with trachea knife, and also esophagus — even flaw of any amount renders treifah; and he did not mention catching fingernail at all, unlike Laws of Beit HaBechirah, where Rambam's intent is to give a sign to the altar: a flaw on it — catching fingernail — he said like a shechitah knife; and this is one who comes to slaughter trachea — and it is strained as I said. But truth guides his way: certainly hard to say the Gemara considers a measure and challenges and answers; and let it say: flaw of knife — what difficulty? Perhaps he holds flaw of knife is on fingernail, and flaw of any amount flaws, as Rambam wrote flaws. Rather clear to my humble opinion, as expert slaughterers agreed with me: there is no flaw in the world, truly the smallest of the small, that will not be felt by fingernail; and if it does not catch, even felt on fingernail — in truth it is not a flaw, only dependent on the checker's feeling; and according to sharpness and intensity of his feeling — some people even a small flaw do not feel; some feel even a hair's-breadth; some feel nothing at all — all according to man's feeling and intensity of his examination; and this is clear and known to all; therefore as tradition and kabbalah came from the Sages, a flaw was catching fingernail, for they spoke regarding a whole man, upright in feeling, without defect; and Torah did not speak of weak feeling and small examination — then no flaw would fail to be felt on fingernail; and this is the proper measure for him — catching fingernail. However, the Sages, for intensity of their holy separation, saw for their souls: perhaps they do not have correct feeling on their parents as fitting for a slaughterer, and do not feel every flaw; therefore they clarified other ways to investigate what does not need so much feeling — in water and sun, etc.; and these are Rambam's words and his supporters, who wrote flaw of any amount — they did not wish to say catching fingernail, lest the slaughterer not be whole in feeling as required and feel a flaw on avshara but not on fingernail, for he does not feel fingernail inhibits him, and he permits not as required; therefore they said plainly: whatever feels on flaw — treifah. But in truth, if the knife came to the hand of one whole in feeling and he testifies he does not feel on fingernail — in truth it is kosher, for the essence of flaw for us by tradition of Maharam is catching fingernail; therefore in Laws of Beit HaBechirah, coming to give a sign according to the general rule and tradition — and sons of understanding, Beit and altar, plainly they are whole in feeling, and immediately God graced them with understanding: flaw — he gave a sign according to Torah and tradition that everything depends on catching fingernail; and plain — examine. And so one may align Rosh's words — at any rate from our words: even a small flaw of smallnesses is forbidden by Torah, even if not felt on fingernail, because the lack is from the checker — if he had felt on the knife that flaw, certainly it would slightly catch fingernail, but his feeling is coarse and he does not feel fineness — and this is clear; and with this all dispute of poskim on this is settled.`,
  '11#א': `One who wishes, etc. — see Shach, seif kaf 18, who lengthened: not like Bach; rather the essence as Rama wrote — and these are Terumat HaDeshen's words. And in truth in Rashba's words there is contradiction: he wrote that requiring checking is only good advice so as not to lose the slaughtered; and afterward he returned and was precise on the wording "requires" — not so, it does not imply good advice but obligation; and therefore he wrote he is obligated — lest he transgress bal teshachet — see there in Terumat HaDeshen and his chiddushim. Behold from this he is obligated, but not from prohibition, as Bach wrote, only from bal teshachet; and practical difference: if treifah meat was bought with kosher meat, perhaps bal teshachet does not apply; nevertheless good advice; therefore in all places they do not distinguish forbidden; and in all Shach brought there is no contradiction to Rashba himself; and so truth is correct; therefore Tur wrote: one must check because of bal teshachet.`,
  '11#ב': `To bring himself in; and if he slaughtered for others and did not check and treifah was found — Taz's view: obligate the slaughterer to pay; Taz in seif kaf 8 disagrees; his proof from the hide that came before Rav, and he exempted — perhaps the law is like one who declares fit; and the same here — perhaps on joint-bone it was flawed; and see that he lengthened. And Nehar Shalom rejected him: the slaughterer knows the law like R' Yosi bar Yehudah, who is lenient on joint-bone; and behold we see in Tosafot Bava Kamma 99, s.v. mine'ach, etc., Rava himself holds the law is valid like R' Yosi bar R' Yehudah — only he was stringent that it is treifah; and Tosafot wrote: therefore he said doubt of theft and not certain theft — that slaughterer would be led to think they will be stringent on him — end; from this it appears like Taz: he should have been led to think they would be stringent; nevertheless Rav exempted; all the more here, where he did not know a flaw would be found and thought the knife would not be flawed in any slaughter — no obligation on slaughterer. But Maharai in Terumat HaDeshen siman 186 stood on this: why indeed did Rav exempt the slaughterer? And he answered: this was not clear to Rav to lead the slaughterer to think they would be stringent on him with such stringency to declare treifah — end. And if so, in our case by law of Gemara requiring checking between each and each, and all slaughterers know there is truly obligation as above to check between one and fellow without putting all animals in presumption of doubt of prohibition, and he was not careful — plainly he was negligent; and your friend will answer: Tosafot there in Bava Kamma deals with other rings and Rav had a doubt and nevertheless exempted — implies on doubt one is exempt; strained to say like Nehar Shalom: the butcher knew Rav permits, the butcher knew — and in truth Nehar Shalom goes to his method that Rav, Shach in Choshen Mishpat 306 seif kaf 10, as Terumat HaDeshen: every stringency spread and known among slaughterers, and he did not do, and thereby it became treifah — he is liable as a damager. But according to Rama there he disagrees; and so appears in Darkei Moshe: even shehiyah in last minority and it became treifah — nevertheless slaughterer exempt; all the more here exempt. And Shach's words: in their days shehiyah in last minority was not spread as certain prohibition — strained, for Rama should have emended according to his view that it does not apply in this time. And in my humble opinion, on this Tur in Choshen Mishpat wrote: and so if knife found flawed and he checked first, since we can say on joint-bone it was flawed — we do not take money from doubt — end; implies: if impossible to attribute such as he held the simanim in hand and slaughtered — clear he did not hit joint-bone — why liable even if flawed in hide? And so Rashba in responsum brought there Kessef Mishneh: exempt, for we say flawed in hide; and Semag and Perishah wished to settle: if flawed in hide slaughterer liable, for certainly his knife was bad, for good knife is not flawed from hide — and this is strained, not like Rashba above; if so, with good slaughterer attribute to joint-bone and animal not treifah; what does Gemara challenge on R' Chiya, daf 10 Chullin, who says flawed on bone — from that which dipped and ascended, etc. — what difficulty? Good knife is not flawed on hide — certainly on bone flawed; or Tur's intent who wrote plainly: and so if found flawed and he checked first — meaning he slaughtered in between and did not check in between, only checked first — if so liable as Taz's view teaches: we do not say on joint-bone afterward flawed; and if we declare treifah he is nevertheless exempt; and Beit Yosef wrote it is similar to Rav's hide; and the matter is clear in Tur's intent according to Semag: what should the butcher do if he takes a sharpened knife — is he a smith to discern iron if flawed on hide or not? And see Tosafot there, s.v. sakin: more common knife flawed on joint-bone last than first; and even though they wrote for R' Hoshaya — nevertheless reasoning did not move, and one does not take money — examine.`,
  '13#_': `Since it went out in permissibility — Bach challenged from seif 15, who ruled in doubt if fell to hard ground — forbidden; and Taz and Shach both answer: here, since it went out in permissibility, it is different; and Shach explains more: here the knife is before us, we establish presumption of prohibition; but in seif 13, where it was lost and permitted, you cannot forbid it afterward. And among them is the reason, even though Peri Chadash rejects him with two hands; nevertheless this is difficult to me: what we say in Chullin — lung was pierced where the butcher's hand was used — do we attribute or not? And Gemara says: reasonable to attribute, for we attribute with a wolf; and Rashi: we say in chapter 1 a wolf came and took the innards and returned them — we do not say at the place of the hole there is a hole. And difficult: what proof? There the wolf already took and they are lost and the matter already went out in permissibility; if you come afterward to forbid because of holes, we say the wolf pierced, as we say with knife he broke bones; but before us, not knowing whence the hole came, we do not attribute to butcher's hand as we do not attribute it fell on its point. Therefore more correct: in seif 13, where knife was lost, there is a good spin and many ways how flaw happened to knife and several doubts — therefore we attribute to be lenient; but in seif 15 we have no doubt the knife is in presumption of flawed, only to say perhaps it fell on its point to earth — and no more than one doubt — we do not permit; not so seif 13, where there is a good doubt the knife was not in presumption of prohibition as above.`,
  '17#א': `He showed his knife to a sage, etc. — it seems specifically constant slaughterer; but occasional slaughterer for episodes — not relevant to show knife to sage; for the opening of their chapter of Chullin they say: all slaughter l'chatchila, even an apostate who eats neveilah for appetite, and he checks knife and gives him; if he did not check he may not slaughter, etc.; and difficult: otherwise l'chatchila he may not slaughter, for he must show knife to sage and is liable to excommunication; and if he showed — you have no more checked knife than that; and perforce all enactment was with a constant butcher, not an occasional one in the world; and the mishnah deals with occasional — correct.`,
  '17#ב': `The sage may forgive — see Shach, who wrote Rambam in chapter 1 of Laws of Shechitah gave reason therefore they excommunicate: because he will rely on himself another time and slaughter with flawed knife — see there. And if so, what helps forgiving where there is concern of prohibition? And in truth Rambam's own words are hard to align: in Gemara they say showing knife to Torah scholar is because of sage's honor, and Rambam gave reason of concern of prohibition. Strained to say: at first he must show to sage because of concern of prohibition as Rambam wrote — otherwise what did the Sages see to divide honor to Torah scholar here more than other things; but if he was established and showed knife to Torah scholar and it was found good time after time — again he is established lest stumbling block go out from under his hand. And nevertheless requires seeing Torah scholar because of sage's honor; and on this the Sages intended sage's honor; and in this way he may forgive — all strained. Therefore it appears to me Rambam holds what Gemara says: if he did not show knife to Torah scholar they excommunicate him; and if the reason is contempt of Torah scholar's honor — what does it teach? We also know one who treats Torah scholar's honor lightly is liable to excommunication. And perforce intent of excommunication is from concern of prohibition; and Rambam holds like what they say regarding one who rules halachah before his rabbi: the matter does not help to rule halachah; and even if Torah scholar forgives it does not help, as Tosafot wrote: for he rules not according to law, even in setting knife and not showing to sage — the matter does not help to set knife on his parents and he will not feel flaw — this truly needs more understanding than ruling; therefore they excommunicate him: since he is unrestrained he will stumble with knife that has flaw — the matter does not help that he set knife properly — and it is strained; and Rambam's words and Gemara as one.`,
});

// --- pitchei-teshuva (11) ---
patchFile('siman_018/pitchei-teshuva/part-001.txt', 'pitchei-teshuva', {
  '1#_': `<b>Flawed.</b> See responsum Brit Avraham, part Yoreh De'ah siman 12, where they asked about a shechitah knife that two slaughterers checked after shechitah and a felt flaw was found; afterward one took the knife and rubbed on forearm flesh and thereby the flaw departed; and the answer in that slaughterer's mouth, who received it in his hand, that any flaw — even if they rub all day — will not be removed; and therefore there was no complete flaw, and the second slaughterer denied him. What is his law? And he brought that this animal is forbidden — see there his reason. [And see responsum Chasam Sofer siman 15 on what slaughterers practice when they find a doubtful flaw in the knife after shechitah — they smooth over hide or something else a while until they do not feel the flaw and declare the animal fit; and he wrote evil is this act, and in my eyes it is like feeding treifot, for a flaw was not told to Moses from Sinai. Hagram and shehiyah were told; and whatever in the knife inhibits — wherever transfer of fingernail is inhibited will be a flaw from the knife body or a protrusion of something else stuck to the knife that cannot be removed easily by hand and light rinsing, etc., only needs some time to smooth on wood and hide, etc. — all cause hagram or shehiyah; therefore whoever does so feeds treifot, and one must stand with strength against these honing destroyers — see there.]`,
  '2#_': `<b>He may not slaughter.</b> Avodat HaGolah; and see Tiferet Moshe, who wrote that according to this error with our knives dedicated to shechitah it is permitted to slaughter relying he will check after shechitah, for b'dieved if he forgets to check it is valid, as in seif 14 — see there. And see responsum Zichron Yitzchak siman 103, who wrote: even if he places another beside him to remind him to check after shechitah — it does not help; for even in Orach Chaim siman 275 regarding reading by candlelight on Shabbat they permitted in such a case — specifically for reading, which is a mitzvah, they permitted — see there.`,
  '3#_': `<b>L'chatchila.</b> Avodat HaGolah; and see Turei Zahav, who wrote they slaughter with it l'chatchila as Taz and Shach; and so plainly Peri Megadim and Chochmat Adam, general rule 3. But in Sefer Shechitot, Miktav Eliyahu wrote it is fitting and correct to define not to slaughter with a rising-and-falling knife, for in error sensation has diminished; would that our debts go out on a smooth straight knife and not on a mountain-and-valley, for sensation of straight knife is not like rising-and-falling; therefore when there is a flaw in the knife one should not hone only at the flaw place, for then it becomes rising-and-falling, but pass honing along the whole knife length until it stands corrected — see there.`,
  '4#_': `<b>Avshara and atufra.</b> Taz: avshara opposite esophagus, atufra opposite trachea. And he wrote in Gan HaMelech siman 57: if he slaughtered fowl on one siman, such as he slaughtered esophagus and the knife was checked avshara — valid even though felt flaw was atufra; or reverse, slaughtered trachea with knife checked atufra even though felt flaw was avshara — it is fine, for these checkings the Sages required — atufra because opposite trachea, and flesh because opposite esophagus — end; and see responsum Meir Netivim siman 36, who lengthened to distinguish and wonder on this — see there; and see responsum Beit Yaakov siman 21.`,
  '5#_': `<b>The fingernail.</b> Avodat HaGolah; and in Sefer Miktav Eliyahu he wrote one should not check the knife when the hand is cold and chilled or very hot, or the hand is moist either from drink or sweat, even moisture not intended to moisten, for he checked and experienced that in all these he will not feel; also wipe the knife so there be no moisture; also when wind blows in the world do not stand outside to check, for wind is difficult for this — see there.`,
  '6#_': `<b>For shechitah.</b> Avodat HaGolah; and see responsum Avodat Avodah, bright faces part 2 siman 140, who ruled like Levush and rejected Taz's words; and see responsum Radbaz, the new ones, siman 280.`,
  '7#_': `<b>Because it is soft.</b> Avodat HaGolah; and see responsum Shevut Yaakov part 2 siman 53, who wrote: if we know the knife touched the joint-bone, that there is a cut in the joint-bone and the flaw is not as great as catching fingernail — one may declare fit from a double doubt: perhaps the law is like Rosh and his colleagues that it is not treifah until it flaws the measure of catching fingernail, and perhaps on the bone it was flawed; and he wrote further an incident came to his hand: the slaughterer said he heard the knife sound when it touched the joint-bone, like they call in Ashkenaz "krek," visible and recognizable — thereby the flaw came from there, and he declared fit; for in such a case all agree we say on the bone it was flawed, since there are legs to the matter — see there; and see Sefer Beli Yadi, who challenged the first law, for he himself ruled in Choshen Aruch siman 46 that double doubt against presumption — we do not say; and on the second law he wrote it seems specifically breaking and not passing; and see Peri Megadim end of the siman, who agreed with Shevut Yaakov on the first law, and on the second wrote one who is lenient in the first instance cannot be blamed — see there.`,
  '8#_': `<b>The sage may forgive.</b> As Shach wrote: for Rambam, who wrote the reason they excommunicate — because he will rely on his shechitah another time and it will be flawed — perhaps there is no difference of sage's forgiveness; and see responsum Brit Avraham part Yoreh De'ah siman 14, letter 3, who wrote there is another practical difference between Rambam's reasons: where the knife was lost, we hold above seif 12 that if they checked it before shechitah it helps — one may say this is specifically if he acted as required and showed to sage; but without showing to sage, even though by law not required except for sage's honor, nevertheless the meat is treifah, since he lost presumption of his fitness — he transgressed sages' enactment; and see there siman 2 letter 15 in gloss, and siman 15 there explained: even nowadays they appoint known men — practical difference where court decreed on him not to slaughter because of suspicion of bribery and he transgressed and slaughtered: since they decreed he not slaughter, they did not forgive, and it is as if he did not show his knife by law of Talmud; and for this reason they excommunicated him — as by law of Talmud, only one who took kabbalah did sages forgive their honor; and therefore one on whom they decreed not to slaughter — they did not forgive — see there.`,
  '9#_': `<b>Settling of mind.</b> See Sefer Shelah, part 4, page 72, who wrote he saw one chasid who did not eat slaughtered meat because he saw by sense of touch the knife was flawed and the slaughterer did not feel this — see there further; and see responsum Beit Yaakov siman 95, who wrote by law one need not be stringent in this except as measure of piety — be stringent on weekdays and not on Shabbat and Yom Tov, for he nullifies a mitzvah if he does not eat meat — see there; and his words are not compelling; see Orach Chaim siman 288, seif 2, and Talmud Chullin daf 11 end 2.`,
  '10#_': `<b>From the community.</b> Avodat HaGolah in the name of Taz; and see responsum Brit Avraham part Yoreh De'ah siman 54, who lengthened on this.`,
  '11#_': `<b>The utensils are forbidden.</b> Avodat HaGolah; and see responsum Brit Avraham, live part, siman 12, letter 3, in the case of a slaughterer who showed his knife in presumption of good and the sage felt a flaw in it; afterward the slaughterer took and rubbed on forearm flesh and thereby the flaw was removed, and he apologized that certainly there was no complete flaw since it was removed by hand rubbing; and he wrote one should not remove him from presumption of fitness to establish he does not feel, for sometimes honing from stone congeals and sticks somewhere on the knife and thereby is felt like a flaw, and by rubbing the congealing was removed; and it can be that from when he gave the knife in presumption of good it had not yet congealed and was moist, therefore he did not feel; and afterward it congealed and therefore is felt, and this was removed by rubbing — see there; and nevertheless it seems everything is according to the matter.`,
});

// --- rabbi-akiva-eiger-yd (6) ---
patchFile('siman_018/rabbi-akiva-eiger-yd/part-001.txt', 'rabbi-akiva-eiger-yd', {
  '1#_': `(Siman 18 seif 12) <b>He must return and check after shechitah.</b> It is difficult for me: behold there is a double doubt that it is not flawed; and even if you say flawed, perhaps on joint-bone it was flawed; and Rama ruled (siman 110, seif 9) that in a double doubt, even where it is possible to clarify, one need not clarify; and even for those who require clarifying — it appears to me this is only if after clarifying we will stand on clarification that it is certainly forbidden or not; but where only one doubt will be clarified, so that afterward there will not be a double doubt but forbidden from one doubt — one may say for all opinions one need not clarify, since now there is a double doubt, and also after clarifying there will not be certain prohibition; with this the difficulty of Shach (siman 110, laws of double doubt, letter 14) is settled — from that of seeing blood due to intercourse: there through clarifying with a tube it will be clarified it is from a source, but still not certain prohibition, for perhaps not all fingers are equal; if so, here with the knife: even if a flaw is found, there will still be doubt perhaps on joint-bone it was flawed — the law is one need not clarify; and it must be that nevertheless in presumption of prohibition, that it is not slaughtered, one must clarify even in a double doubt — and in such a case.`,
  '2#_': `(There) <b>But if it was lost, his shechitah is valid.</b> Rambam's wording; and also if he was negligent and did not check the knife, or it was lost.`,
  '3#_': `(There) <b>And if he touched the joint-bone.</b> See Rashba in Terumat HaDeshen and Chiddushei Rabbi Akiva Eiger, that we hold like this establishment that we establish Rav Kahana like R' Chiya, and to validate the second — for in Torah law we follow the stringent; and this establishment is for stringency of R' Chiya, who makes animal shechitah like breaking bones — say he touched joint-bone and knife was flawed; and if he slaughtered and knife was lost — all are forbidden from the second onward; and R' Hoshaya for leniency and R' Chiya for stringency; and even though we do not attribute joint-bone in one animal to be lenient — we are concerned for R' Chiya's view if he slaughtered two or three animals; and Rashba concludes in Chiddushei Rabbi Akiva Eiger: one who is stringent — blessing upon him; and I did not merit to understand this method — how is it proven from this wording that animal shechitah makes the knife not checked? We only find: if after the last a flaw is found, all from second onward are forbidden; and he does not hold like the reasoning that we say above: from when they attribute, perhaps on the second it was flawed — we mean the reasoning is actually difficult, since R' Chiya's reason is bone certainly flaws, hide doubtfully flaws; but regarding in which bone it was flawed, first or second — there is no such distinction; and perforce we must push that the reasoning of this wording: he is more careful at first than at last, and more reasonable to attribute on last than on first; and as Tosafot wrote; and if so, plainly one may say: for this establishment of Rav Kahana like R' Chiya and to validate the second — he holds like the books, that plainly we attribute on last more than on first; therefore all are forbidden; but when lost — whence do we have that R' Chiya is more stringent and judges it as unchecked knife? And even though this method is proven from the Talmud's challenge — if so, sage's checking is required; and this is only if we judge the knife is included in "not checked" and forbidden to slaughter by law without checking; nevertheless it itself is difficult: whence for the Talmud to challenge how proven from this wording that he makes it unchecked? And possible to settle with strain. But more wondrous to me in what he wrote: here R' Hoshaya for leniency and R' Chiya for stringency — where do we find R' Hoshaya lenient here? From that we do not attribute flaw on joint-bone there is no proof, for R' Hoshaya is stringent even when he broke bones, for certainly he makes it unchecked; and what they challenge: if so, sage's checking is required — R' Hoshaya's wording is fine, but this is what they say: for R' Hoshaya's first wording, to invalidate the first, one may say the knife did not become unchecked; but for this wording of R' Chiya, to validate the second — meaning through shechitah it became unchecked; and in truth automatically all the more for R' Hoshaya it is so, for we do not find R' Hoshaya more lenient than R' Chiya — sage's checking required for all, even according to R' Hoshaya; and apparently this is the plain and very spacious way; and I rejected; and see Rashba there: Ramban's view — for R' Hoshaya also one who slaughters with checked knife and it was lost — forbidden, for animal while alive in presumption of prohibition until known; and knife checking inhibits; and difficult for me: if so, difficulty on R' Hoshaya from baraita their kids and chickens were lost — what helps that majority present are experts? Behold before us there is no checking after shechitah, for perhaps truly knife flawed after shechitah; for regarding checking simanim that inhibits, one may say since he is expert he checks simanim, and when he sees not slaughtered, majority finishes immediately shechitah, as rishonim on apostate; but for knife checking — not so; and we must push R' Hoshaya holds they argue first tanna and R' Yehuda: truly R' Yehuda forbids for this reason, perhaps knife found flawed; and as Tosafot beginning chapter, for Ravina, who holds like R' Yehuda; and he holds R' Yehuda's reason: not majority present; and not as rejected, they argue in found in ash heap; and still requires study.`,
  '4#_': `(Seif 15) <b>And after shechitah he broke bones in it.</b> According to what Tosafot wrote in one answer: what we answer on it that R' Chiya on that of dipped and ascended — knife deteriorated, animal not deteriorated — there is no place to distinguish, but rather we say thus: even if knife deteriorated, still animal not deteriorated, for perhaps he slaughtered not at the place of the flaw; and we were so in a long knife like two necks full; if so, automatically for us too when he broke bones in it likewise, for even when he broke bones it is hard like dipped and ascended, since he busied with that species it is like breaking bones; and the Talmud's wording must be changed: knife deteriorated; and if so, with a small knife that is not so — forbidden.`,
  '5#_': `(Shach, seif kaf 31) <b>And Darkei Moshe brings it.</b> And in Damascus Eliezer he wrote: to take korkeshot from kosher and from treifot too is forbidden, for korkeshah of kosher is worth more than korkeshah of treifah.`,
  '6#_': `(Taz, seif kaf 15) <b>It implies; but by law.</b> See responsum Mahari HaLevi, brother of Taz, siman 17.`,
});

// --- nekudot-hakesef (1) ---
patchFile('siman_018/nekudot-hakesef/part-001.txt', 'nekudot-hakesef', {
  '1#_': `(Siman 18, seif kaf 8) <b>For it is in chapter HaGozel, etc.</b> In my humble opinion there: the slaughterer did not bring himself into doubt, for he had no doubt at all; rather he was established like R' Yosi; and if so, even though for Rav there is doubt — that is regarding treifah, but not to take money, for perhaps the law is like R' Yosi; but here he brought himself into doubt. Also what he challenged: here damage is not certain, etc. — in my humble opinion: perforce we do not require damage certain except for gerama; but here he damages with his hands, for he slaughters with his hand with a flawed knife; if so, he should not have brought himself into doubt; and all the more since the way of the knife is to flaw when slaughtering much — behold it is like damage certain.`,
});

// --- kaf-hachayim (20) ---
patchFile('siman_018/kaf-hachayim/part-001.txt', 'kaf-hachayim', {
  '1#_': `(Seif 1) One who slaughters with a checked knife and it is found flawed, even from the side. And this does not include knife markings craftsmen make when making the knife, since it is far from the point — so Maharshal; Taz, seif kaf 1; and so above siman 9, letter 6, in the name of several poskim; and see there further from letter 7 onward, laws pertaining to this matter — see there.`,
  '2#_': `(There) Gloss: even from the side. And so is Shulchan Aruch's view, as written below seif 9; and so Shulchan Gavoah, letter 2.`,
  '3#_': `(There) Behold it is neveilah. Because the flaw does not cut but tears and pierces the simanim at its point and renders the animal neveilah, as in Gemara (Chullin 17b), and Scripture writes "and you shall slaughter," not "and you shall tear." And so Levush; Minchat Yosef, letter 1.`,
  '4#_': `(There) Behold it is neveilah. Explanation: doubtful neveilah; and as he concludes "but rather we are concerned," etc.; and so in seif 11; therefore he wrote below siman 28, seif 20, that in such a case one covers without blessing — see there; Shach, seif kaf 1, in the name of several poskim; and so Peri Chadash, letter 2; Shulchan Gavoah, letter 3; Kereti, letter 1; Zivchei Tzedek, letter 2; Yad Eliyahu, letter 1. However, Knesset HaGedolah in Hagahot Tur, letter 3, wrote: here it is certainly neveilah; and so Shapirdatz, letter 1; and he wrote to distinguish between there and here — see there; however Shulchan Gavoah there agreed with Shach that it is doubtful neveilah; and therefore he wrote for practical law: one who eats its flesh is not lashed and cannot slaughter on the first day; and if he slaughtered he is not lashed on a doubt — see there.`,
  '5#_': `(There) But rather we are concerned, etc. Because animal while alive stands in presumption of prohibition (prohibition of limb from a live animal) and does not leave prohibition until you know with what it was slaughtered; and since doubt arose in it, it has not been clarified it was slaughtered properly, as below end of siman 25 in gloss; Shach, seif kaf 2; Peri Chadash, letter 3; Lechem HaPanim, letter 2; Kereti, letter 2; Zivchei Tzedek, letter 3.`,
  '6#_': `(There) And even in fowl. Even if he also touched the joint-bone — for there are two reasons to be lenient, its measure is soft, and he touched the joint-bone — nevertheless we are concerned lest it was flawed in the hide; Bach; Shach, seif kaf 3; Peri Chadash, letter 4; Lechem HaPanim, letter 3; Beli Yadi, letter 2; Kereti, letter 3; Zivchei Tzedek, letter 4; Zivchei Tzedek, letter 3; Yad Eliyahu, letter 4.`,
  '7#_': `And even — he slaughtered only the trachea, and there is a good doubt: perhaps afterward it was flawed; and even if you say from before: perhaps he touched the flaw before he slaughtered half the trachea — if so the flaw does not flaw; nevertheless forbidden, for any doubt in shechitah is forbidden — Kereti there.`,
  '8#_': `And even — they did not check it many hours after shechitah, and afterward checked and found flawed — nevertheless we are concerned lest it was flawed in the hide; and we do not say it is a double doubt — perhaps on joint-bone flawed, perhaps after shechitah flawed by something else; Yad Eliyahu, letter 3; and to me it seems plain it is not a double doubt, since it does not reverse: the two doubts are after shechitah; and if you say before shechitah — it is neveilah, and we do not make such a double doubt, as written siman 110, laws of double doubt — see there.`,
  '9#_': `(Seif 2) The measure of a flaw is any amount. Secret of knife checking that it not be flawed — for benefit of the soul dwelling in animal and fowl that shechitah not be invalidated and they not suffer further; Avodat HaKodesh, part 63; Lechem HaPanim, letter 4; Zivchei Tzedek, letter 8; and meaning: aside from what is halachah leMoshe miSinai, there is further benefit for the dwelling soul; and intent of knife checking and shechitah we already wrote in Orach Chaim siman 245, letter 7 — see there.`,
  '10#_': `(There) The measure of a flaw is any amount, etc. In Gemara (Chullin 17b) many amoraim are cited who were stringent in checking — to check in sun or in water; when one passes its point on water, if flaw in knife they feel it in water — and that is even any amount; and Maharshal concludes in Yeshuot Yaakov, chapter 1 of Chullin siman 38: these amoraim who checked in sun and water — a stringency they added to check after all doubts; and we conclude the law: with these checkings of avshara and atufra it suffices; but certainly if a flaw of any amount is found in sun and water — it is treifah, even b'dieved — see there; Bach, Taz, seif kaf 2; and so Knesset HaGedolah in Hagahot Beit Yosef, letter 5: custom to check on fingernail and flesh; but certainly if a small flaw visible in sun and water is found, even if not felt on fingernail and flesh — invalid, Rambam's words — see there; and so Beli Yadi, letter 3; and such is Taz's view, siman 89, letter 13; Zivchei Rishon, siman 10, in Tamidim, letter 2.`,
  '11#_': `And there are those who practice seeing the knife point with the eye's vision too, aside from avshara and atufra checking, as Darkei Moshe wrote, letter 3; and Zivchei Rishon in Musafim, letter 9; and in letters afterward.`,
  '12#_': `(There) The measure of a flaw is any amount, etc. And so Shach, seif kaf 4: the custom is plain to invalidate even a flaw of any amount, not like Bach — see there; and so Peri Chadash, letter 5; Peri Toar, letter 3; Lechem HaPanim, letter 5; Chochmat Adam, general rule 3, letter 11; and this is according to law of Talmud and Shulchan Aruch and several more poskim; but our custom is to forbid even any sensation, even though it does not inhibit a hair's-breadth and is not visible to the sun; and also forbid not to slaughter if before shechitah one sees like a flaw of any amount by sun vision, even though it does not inhibit a hair's-breadth and is not felt on fingernail; and in my opinion correct to do so — see l'chatchila by sun vision on knife point, and be precise that he not find even a bit of whiteness, for even though this is not a flaw, nevertheless through shechitah lightly it will flaw there; therefore do not slaughter with knife until there be no sensation at all and its sharpness black to the eye's vision from head to end without white point; whoever practices thus — good for him; Komtzo, letter 3. However, this is certainly plain: Heaven forbid to rely on vision checking alone without fingernail checking — for aside from transgressing Sages' words who require fingernail specifically, they said expert slaughterers: there are flaws not visible in vision and felt in fingernail checking; and one who relies on knife checking by eye vision alone is among those who feed neveilah; Darkei Torah, letter 20; and as appears from poskim' words that vision helps only to be stringent, not to be lenient, Heaven forbid.`,
  '13#_': `And Peri Toar wrote, letter 3: already known and plain that an expert checker feels on fingernail less than a hair's-breadth; and those who feel more — in any case of checking let them feel more; a checker until where his hand reaches. And so Peleti, letter 1: clear to my humble opinion, as expert slaughterers agreed with me: there is no flaw in the world, truly smallest of small, not felt by fingernail, etc.; only everything depends on checker's feeling and sharpness and intensity of his feeling — some do not feel small flaw, some feel even hair's-breadth, some feel nothing — all according to man's feeling and intensity of examination; and this is clear and known to all — end; and so Chochmat Adam, general rule 3, letter 11: one whole in mind feels on fingernail even flaw like hair's-breadth; therefore the finest thin flaw — all is called measure of catching fingernail — see there. Moral of all said: regarding knife checking one needs sharpness, expertise, and intensity of feeling; everything depends on settling mind and fear of Heaven, as written below seif 17 — see there.`,
  '14#_': `And certainly one need not check the knife by vision through a glass vessel that magnifies sense of sight; Totafot Yoreh De'ah, second, in omissions siman 53; and so in responsum Mar VeAhilot, in tent of blessings and thanks siman 30, s.v. atzig; Darkei Torah, letter 20.`,
  '15#_': `And if there is a crack in its point somewhat deeper than a hair's-breadth, even though a hair's-breadth does not enter — for there is no flaw and deficiency, and the points are right next to each other, and flesh and fingernail do not catch there — nevertheless concern: in pressing on simanim the crack may open somewhat and catch in siman, and forbidden even b'dieved; Shemirat Shabbat, letter 2; Komtzo, letter 4; and Chochmat Adam there agreed to forbid for another reason — see there; Zivchei Tzedek, letter 6.`,
  '16#_': `Because all rust is judged like a flaw and rust; and sometimes there is no flaw in knife but from rust it appears like flaw, as I saw and checked several times; and also possible to invalidate from shehiyah; therefore rinse the knife before checking in water; Knesset HaGedolah in Hagahot Beit Yosef, letter 2, in the name of Darkei Moshe; Zivchei Shlomo, letter 2; Zivchei Tzedek, letter 7; and therefore some practice placing a little saliva on the cloth to clean the knife before checking.`,
  '17#_': `(Seif 3) One must check the knife before shechitah. And we do not bless on knife checking like on shechitah, for any mitzvah whose performance does not complete its work — meaning complete the mitzvah — we do not bless on it; proof from sukkah that we do not bless on making it; and knife checking — its performance does not complete work, for afterward shechitah is needed; Mahari Weil in glosses of R' Yerucham; Knesset HaGedolah in Hagahot Tur, letter 9; and also lest he reconsider and not slaughter — and it is a blessing in vain; Lechem HaPanim, letter 6; Zivchei Rishon in Musafim, letter 1; and further because we do not bless on any mitzvah that is not the essence of the mitzvah, as written in our words Orach Chaim siman 8, letter 2; and here the essence mitzvah is shechitah.`,
  '18#_': `(There) One must check the knife before shechitah. And in this there are three reasons. One: lest he forget to check afterward and behold he eats neveilah. Two: because of concern of blessing in vain. Three: because forbidden to render animal neveilah for nothing, for he transgresses bal teshachet; Shemirat Shabbat, letter 1; and even if he heard the blessing from another — no concern of blessing in vain; and also neveilah equals kosher — no bal teshachet; and hidden knife — then perhaps he will rely and not check afterward — no prohibition; nevertheless one should be careful not to slaughter without checking first, for even hidden knife may easily flaw by itself, and one may not rely on guarding it; also even though neveilah equals kosher — forbidden to cause treifot because of pain to living creatures; and all the more according to the secret one should be concerned to repair sparks of holiness or those dwelling, as known; Mechaber's letter, letter 2, not like Shapirdatz, letter 5; Zivchei Shlomo, letter 4; Zivchei Tzedek, letter 9; Minchat Yitzchak, letter 1.`,
  '19#_': `And even if he places another beside him to remind him to check after shechitah — it does not help; for even in Orach Chaim siman 275 regarding reading by candlelight on Shabbat they permitted in such a case — specifically reading, which is a mitzvah, they permitted; responsum Zichron Yitzchak siman 103; Pithei Teshuvah, letter 2; and Zivchei Tzedek agreed, letter 10, for other reasons.`,
  '20#_': `And our knives dedicated to shechitah — permitted to slaughter relying he will check after shechitah, for b'dieved if he forgets to check it is valid, as below seif 14; Pithei Teshuvah there in the name of Tiferet Moshe. However, in gloss there seif 14 it implies even such a knife forbidden to slaughter l'chatchila without checking — see there; and so Komtzo, letter 1; Zivchei Rishon, letter 1; Yad Eliyahu, letter 7; and so above, letter 18.`,
});

// --- yad-avraham (4) ---
patchFile('siman_018/yad-avraham/part-001.txt', 'yad-avraham', {
  '1#_': `(Siman 18 seif 4) <b>A knife that one checked on holacha and did not feel a flaw, and when he brought it back on hava'ah he felt a flaw, etc.: if he slaughtered by holacha alone and did not bring back his shechitah is valid; if he brought back, invalid.</b> It appears to me plainly proven in Talmud, Rashi, Tosafot, Rif, Rambam, Rosh, Rashba, Ran, Mordechai, Tur, Beit Yosef, Shulchan Aruch, gloss, and Shach in this siman that a flaw invalidates in the last minority according to all; for here perforce it deals where he slaughtered the measure of shechitah on holacha alone — meaning there is in the knife measure of two necks, as explained siman 24; and nevertheless if he brought back, invalid — evidently flaw invalidates in last minority; and this is not like Maharitz whom Shach brings siman 23, seif kaf 13 — see there — in whose old age all those poskim were hidden from him.`,
  '2#_': `(There) <b>If he slaughtered by holacha alone and did not bring back — his shechitah is valid.</b> And it appears to me: if the flaw is at the end of the knife — forbidden, lest he withdrew his hand slightly and did not feel; as Rashba and Ran and Taz wrote, seif 5; and so explicitly in Hagahot Maimonit, chapter 1 of Laws of Shechitah, law 13.`,
  '3#_': `(Shach, seif kaf 25) <b>But Rambam, etc.: they wrote the reason they excommunicate because he will rely on his shechitah another time and it will be flawed and he will slaughter with it — end; however in Talmud chapter 1 of Chullin (daf 10b) it appears like Rashi and Ran — end.</b> And Lechem Mishneh also challenged thus on Rambam, who gave a reason not mentioned in Gemara. And behold also from Tosafot Bechorot (daf 31) and Rosh, chapter 2 of Negaim, it is proven he too holds like Rambam: showing knife to sage — they did not touch it only for his honor, but also from concern of prohibition; he brings proof: a Torah scholar is trusted to rule for himself in prohibition and permissibility where prohibition was not established — from what they say, chapter HaDar: a Torah scholar may rule for himself — knife checking, and need not show to sage; and if it were that showing knife to sage is only for honor — it would not apply to derive ruling of prohibition and permissibility; rather we learn he holds like Tosafot and Rosh that there is also prohibition; and so from Nemukei Yosef, chapter 10 of Bava Batra — see there. And Shach's difficulty from chapter 1 of Chullin — he already answered in his long book: we do not say a person is trusted in prohibitions except regarding kosher, not regarding invalid; and this one who did not show his knife to sage is not called kosher, for he transgressed sages' enactment, and he is no longer trusted, and we are concerned lest he do prohibition once; and there is support for this: such we find regarding blemishes of firstborn in Bechorot (daf 36): that clear blemish must be shown to sage is for his honor; and nevertheless there (daf 28) if he did not show to sage and it was slaughtered — forbidden, because of decree: we decree on internal blemishes that do not change after shechitah lest blemishes that change; behold even though the beginning of the enactment to show to sage was for his honor and not because of prohibition decrees — nevertheless when he transgressed and did not show to sage, we are concerned lest he come to prohibition. And the same: they said at first to show knife to sage only for honor and did not concern for prohibition; nevertheless when he transgressed and did not show, we are concerned now lest he come to prohibition; therefore they excommunicated him, and sage's forgiveness does not help.`,
  '4#_': `(Seif 18 in gloss) <b>In some places they practice that a person does not slaughter and check for himself.</b> It seems this is one who slaughters for himself and not to sell to others — and this is only from custom's power; but when he slaughters for himself and sells to others — by law forbidden, for suspected to declare treifah fit, as explained plainly in Rambam chapter 8 of Laws of Me'ilah, laws 7, 83, 91; and Tur and Shulchan Aruch, end of siman 65; and he learned this from Talmud Avodah Zarah (daf 38): one does not buy meat in Syria except from an expert; and Rashi there: they are suspected, for they are not careful before skin; but they themselves are not suspected to eat prohibition, as Rama siman 119 in gloss; and it is surprising on one of the acharonim who wrote the opposite: the gloss here deals with one who slaughters for himself and sells to another — this alone is forbidden from custom's power; and I did not grasp his final view; for we cannot say he meant only one established in fitness — if so, there is also no custom.`,
});

// --- yad-ephraim (4) ---
patchFile('siman_018/yad-ephraim/part-001.txt', 'yad-ephraim', {
  '1#_': `<b>Within the flaw of the fingernail.</b> Avodat HaGolah; and what he wrote in the name of Darkei Shalom siman 4 is a printing error — it should be siman 200; and see there he wrote there is no question to check this shechitah knife on the thumb finger, even though it is the thickest and heaviest of fingers; permission is given to check with whichever hand and finger he feels most, according to his own knowledge and sense of touch; and it happens every day that several slaughterers check on index finger or middle finger, each according to his feeling, even though we did not see one who checks on thumb — perhaps one will be found who feels more on it than other fingers; and doctors in feeling pulse prove: some do not feel on thumb because of the pulse vein there; some feel and feel more on it. And see what Avodat Avodah wrote in Tiferet Shlomo: that which Lechem HaPanim wrote to check specifically on thumb — no concern for this, and we do not practice thus; and he wrote in responsum Avkat Rokhel on a slaughterer who did not feel a catching flaw — one should not remove him for this, since one can attribute that because of fear they commanded him to check before many great ones; but if it becomes clear he has no feeling at all — and so in all places they remove by law — they declare treifah everything retroactively; but if he says, "It is clear to me I slaughtered without flaw" — see there. And it seems treifah retroactively until the hour it was checked before a sage and he saw he has feeling — then they say afterward it deteriorated; and Meir Netivim siman 35 wrote one should not rely on atufra checking alone when felt on avshara, even if slaughtering trachea; and likewise reverse when felt on atufra even if not felt on flesh — forbidden even if slaughtering esophagus alone; Heaven forbid to do so, not like Sefer Gan HaMelech; and he too possibly did not say so except for pilpul — see there.`,
  '2#_': `<b>Because it is soft.</b> Avodat HaGolah; and he wrote in Shevut Yaakov part 2 siman 53: one who slaughtered with checked knife and flaw found, and certainly he did not touch joint-bone, for even simanim were not slaughtered and flesh of joint-bone intact on all sides; and he brought from Tur and Beit Yosef, Choshen Mishpat siman 306 in the name of Rashba: Rashba who exempts from paying deals with the animal-owner's knife — then if flawed in hide the butcher is not negligent if he did not check before shechitah; not so when the knife is the slaughterer's — then he was negligent for not having a good knife that will not flaw on animal's hide; and Tur deals with this, and there is no dispute — see there; and Shevut Yaakov siman 53: if we know the knife touched joint-bone — if there is still room to be lenient, such as flaw not as great as catching fingernail — there is a double doubt: perhaps law is like Rosh, etc.; perhaps on bone flawed; and flaw not so great — declare fit; also an incident: slaughterer heard knife sound on joint-bone like "krek" in Ashkenaz — recognizable thereby flaw came from there, and he declared fit; in such case all agree we say on bone flawed since legs to matter — see there; and he wrote in place of Shmuel siman 33: knife found flawed after shechitah — flaw that does not catch fingernail; they checked joint-bone and large cut found in joint-bone in depth of bone — declare fit, attribute to joint-bone, as appears from Tosafot Chullin daf 10 and Mordechai and Rosh and Beit Yosef in what he wrote to settle Tur's words in the name of Baal HaItur; and so other poskim; and so in Shechitot Mahara of Prague: large flaw found on knife and the three great men commanded to look after joint-bone and cut found — declared fit; and specifically cut in bone itself; but in white surrounding bone, which is soft — we do not attribute, for there the knife was flawed — end. And all the more in our case where it did not catch fingernail — see there.`,
  '3#_': `<b>And he need not excommunicate him.</b> Avodat HaGolah; and see responsum Nachalat Shiva siman 15 on a slaughterer who ruled on an animal shaking its head and somewhat congealed matter found in the brain; the slaughterer showed it kosher, the membrane exists — since it required a sage's question and to see if brain surrounds the deficiency, concern lest laymen there, not Torah scholars, say in their opinion it surrounds; and possible if it came before the teacher he would declare treifah; and even if truly kosher — nevertheless do not forgive the excommunication; and see there he wrote: what sages forgave their honor in knife checking is toward slaughterers who trust them for shechitah and checking; but forbidden for slaughterer to give knife to check to one who is not their slaughterer — sages did not forgive honor except to appointees from their mouth on shechitah.`,
  '4#_': `<b>Like from the kosher.</b> Avodat HaGolah; and he wrote in responsum Ein Mishpat siman 1: an Israelite hired by a non-Jew to sell him kosher and treifot, and the Israelite takes wages of animals' lungs for selling them and the money for himself — in such a case forbidden, for through wages of his toil he buys lungs, profits in body money, and it is not like happenstance, even though he gives him animals alive — he tends them to slaughter and flay; nevertheless Israel has no acquisition in them and treifah is found in non-Jew's possession and happened to non-Jew; when Israel takes them it is like buying to profit; rather sell meat and lungs on non-Jew's purse and take wages from all sale money, even from lung money itself, provided he does not designate lungs for him; and such is permitted, for wages of prohibited food goods are permitted — see there.`,
});

